      this._subscribeToPositions(
        config.positionStrategy as FlexibleConnectedPositionStrategy
      );
      this._overlayRef = this._overlay.create(config);

      // Consume the `keydownEvents` in order to prevent them from going to another overlay.
      // Ideally we'd also have our keyboard event logic in here, however doing so will
      // break anybody that may have implemented the `OuiPanelOverlay` themselves.
      this._keyboardEventSubscription = this._overlayRef
        .keydownEvents()
        .pipe(filter((event) => event.key === 'Escape'))
        .subscribe(() => this.closePanel());
    }
    return this._overlayRef;
  }

  /**
   * This method builds the configuration object needed to create the overlay, the OverlayState.
   *
   * @returns OverlayConfig
   */
  private _getOverlayConfig(): OverlayConfig {
    return new OverlayConfig({
      positionStrategy: this._overlay
        .position()
        .flexibleConnectedTo(this._element)
        .withLockedPosition()
        .withTransformOriginOn('.oui-panel-overlay'),
      backdropClass: 'cdk-overlay-transparent-backdrop',
      scrollStrategy: this._scrollStrategy(),
      direction: 'ltr',
    });
  }

  /**
   * Listens to changes in the position of the overlay and sets the correct classes
   * on the menu based on the new position. This ensures the animation origin is always
   * correct, even if a fallback position is used for the overlay.
   */
  private _subscribeToPositions(
    position: FlexibleConnectedPositionStrategy
  ): void {
    if (this.panel.setPositionClasses) {
      position.positionChanges.subscribe((change) => {
        const posX: PanelPositionX =
          change.connectionPair.overlayX === 'start' ? 'after' : 'before';
        const posY: PanelPositionY =
          change.connectionPair.overlayY === 'top' ? 'below' : 'above';

        this.panel.setPositionClasses!(posX, posY);
      });
    }
  }

  /**
   * Sets the appropriate positions on a position strategy
   * so the overlay connects with the trigger correctly.
   *
   * @param positionStrategy Strategy whose position to update.
   */
  private _setPosition(positionStrategy: FlexibleConnectedPositionStrategy) {
    const panelPositions = new PanelFlexiblePosition(
      this.panel.xPosition,
      this.panel.yPosition
    );
    positionStrategy.withPositions(panelPositions.getPosition());
  }
  /**  assign large width if overlay element contains img tag */
  private _setLargeWidth() {
    const imageTag = this._overlayRef.overlayElement.querySelector('img');
    if (imageTag) {
      const content: HTMLDivElement =
        this._overlayRef.overlayElement.querySelector('.oui-panel-content');
      content.classList.add('oui-panel-content-large');
    }
  }

  /** Cleans up the active subscriptions. */
  private _cleanUpSubscriptions(): void {
    this._closeSubscription.unsubscribe();
    this._hoverSubscription.unsubscribe();
    this._escapeEventSubscription.unsubscribe();
    this._keyboardEventSubscription.unsubscribe();
  }

  /** Closes the menu and does the necessary cleanup. */
  private _destroyPanel() {
    if (!this._overlayRef || !this.panelOpen) {
      return;
    }
    this._setIsPanelOpen(false);
    const panel = this.panel;

    this._closeSubscription.unsubscribe();
    this._overlayRef.detach();

    if (panel.lazyContent) {
      panel.lazyContent.detach();
    }
  }

  /** Closes The Panel */
  closePanel(hoverType?) {
    this.panel.closed.emit();
    if (!hoverType) {
      this._restoreFocus();
    }
  }

  /** Moves the focus inside the focus trap. */
  public _trapFocus() {
    const element: HTMLDivElement =
      this._overlayRef.overlayElement.querySelector('.oui-panel-content');

    if (!this._focusTrap) {
      this._focusTrap = this._focusTrapFactory.create(element);
    }
    element.focus();
  }

  /** Restores focus to the element that was focused before the panel opened. */
  public _restoreFocus() {
    const toFocus = this._currentFocusElement;
    // We need the extra check, because IE can set the `activeElement` to null in some cases.
    if (toFocus && typeof toFocus.focus === 'function') {
      toFocus.focus();
    }

    if (this._focusTrap) {
      this._focusTrap = null;
    }
  }

  /** Gets the portal that should be attached to the overlay. */
  private _getPortal(): TemplatePortal {
    // Note that we can avoid this check by keeping the portal on the menu panel.
    // While it would be cleaner, we'd have to introduce another required method on
    // `OuiPanelOverlay`, making it harder to consume.
    if (!this._portal || this._portal.templateRef !== this.panel.templateRef) {
      this._portal = new TemplatePortal(
        this.panel.templateRef,
        this._viewContainerRef
      );
    }
    return this._portal;
  }

  public _handleMouseEnter(event: MouseEvent): void {
    // On hover it will focus on the element itself
    const focusElement = event.target as HTMLElement;
    this._currentFocusElement = focusElement.querySelector('oui-icon');
    this._mouseEnter.next(event);
    this.openPanel();
    event.stopImmediatePropagation();
  }

  public _handelMouseLeave(event: MouseEvent): void {
    this._mouseLeave.next(event);
    event.stopImmediatePropagation();
  }

  /** Returns a stream that emits whenever an action that should close the panel occurs. */
  private _panelClosingActions(): Observable<any> {
    const detachments = this._overlayRef!.detachments();
    const mouseLeave = merge(
      this._mouseLeave.asObservable(),
      this._mouseEnter.asObservable(),
      this.panel.mouseLeave,
      this.panel.mouseEnter
    ).pipe(
      debounceTime(200),
      filter((event) => event.type === 'mouseleave')
    );
    return merge(detachments, mouseLeave);
  }

  ngOnDestroy() {
    if (this._overlayRef) {
      this._overlayRef.dispose();
      this._overlayRef = null;
    }
    this._cleanUpSubscriptions();
  }
}

import {
  AfterViewInit,
  Directive,
  ElementRef,
  EventEmitter,
  inject,
  NgZone,
  OnDestroy,
  Output,
  PLATFORM_ID,
  Renderer2,
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

export interface ColumnOrderChangedEvent {
  /** Original column index (before drag). */
  previousIndex: number;
  /** Target column index (where it was dropped). */
  currentIndex: number;
  /**
   * Full ordered array of column IDs after the move.
   * Consumer should assign this to displayedColumns.
   */
  columnIds: string[];
}

@Directive({
  selector:
    'oui-table[ouiReorderableColumns], table[oui-table][ouiReorderableColumns]',
  standalone: false,
})
export class OuiReorderableColumnsDirective
  implements AfterViewInit, OnDestroy
{
  /** Emitted when a column is dropped in a new position. */
  @Output() columnOrderChanged = new EventEmitter<ColumnOrderChangedEvent>();

  private _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  private _renderer = inject(Renderer2);
  private _ngZone = inject(NgZone);
  private _platformId = inject(PLATFORM_ID);

  // ─── Live state ──────────────────────────────────────────────────────────────
  private _headerCells: HTMLElement[] = [];

  // ─── Per-drag state ───────────────────────────────────────────────────────────
  private _dragging = false;
  /** True from pointerdown until full cleanup — guards MutationObserver re-attach. */
  private _dragActive = false;
  /** True while _onPointerUp is running — prevents lostpointercapture from re-entering cleanup. */
  private _pointerUpInProgress = false;
  private _sourceIndex = -1;
  private _startX = 0;
  private _startY = 0;
  /** Offset from cursor to cell left edge at pointerdown — keeps ghost pinned under cursor horizontally. */
  private _cursorOffsetX = 0;
  /** Offset from cursor to cell top edge at pointerdown — keeps ghost pinned under cursor vertically. */
  private _cursorOffsetY = 0;
  private _columnIds: string[] = [];
  /** CDK column ID of the currently highlighted target column. */
  private _highlightedTargetColumnId = '';
  /**
   * The insertion slot index: the column will be inserted BEFORE this index.
   * A value equal to _headerCells.length means "insert at the very end".
   */
  private _insertionSlot = -1;
  private _ghost: HTMLElement | null = null;
  private _dropIndicator: HTMLElement | null = null;

  // ─── Per-drag cell-level listeners (set once per drag, cleaned up on pointerup) ─
  private _dragMoveUnlisten: (() => void) | null = null;
  private _dragUpUnlisten: (() => void) | null = null;
  private _dragCancelUnlisten: (() => void) | null = null;
  private _dragLostCaptureUnlisten: (() => void) | null = null;
  private _dragSelectStartUnlisten: (() => void) | null = null;
  private _dragNativeDragUnlisten: (() => void) | null = null;

  // ─── Document-level pointerup fallback (always fires, even if cell listeners fail) ─
  private _docPointerUpHandler: ((e: PointerEvent) => void) | null = null;

  // ─── Persistent pointerdown listeners (one per header cell) ──────────────────
  private _cellUnlisteners: (() => void)[] = [];

  // ─── MutationObserver to auto-refresh when columns re-render ─────────────────
  private _mutationObserver: MutationObserver | null = null;

  // ─── ResizeObserver to detect table overflow and toggle shadow class ─────────
  private _overflowObserver: ResizeObserver | null = null;

  // ─── Auto-scroll state (used while dragging) ────────────────────────────────
  private _scrollContainer: HTMLElement | null = null;
  private _scrollRafId = 0;
  /** True while the RAF loop should keep scrolling (cursor in edge zone). */
  private _scrollWanted = false;
  /** Last known pointer position — used by the RAF loop after a scroll tick. */
  private _lastClientX = 0;
  private _lastClientY = 0;
  /** Width (px) of the edge activation zone. Cursor inside this region triggers auto-scroll. */
  private readonly _scrollZoneSize = 50;
  /** Maximum pixels scrolled per animation frame when cursor is at the very edge. */
  private readonly _scrollMaxSpeed = 12;

  ngAfterViewInit(): void {
    if (!isPlatformBrowser(this._platformId)) {
      return;
    }
    this._ngZone.runOutsideAngular(() => {
      setTimeout(() => {
        this._attachCellListeners();
        this._watchHeaderRow();
        this._watchOverflow();
      }, 0);
    });
  }

  // ─── Cell listener management ─────────────────────────────────────────────────

  private _attachCellListeners(): void {
    this._detachCellListeners();
    this._headerCells = Array.from(
      this._elementRef.nativeElement.querySelectorAll<HTMLElement>(
        'oui-header-cell, th[oui-header-cell]'
      )
    );

    this._headerCells.forEach((cell, idx) => {
      const unlisten = this._renderer.listen(
        cell,
        'pointerdown',
        (e: PointerEvent) => {
          // First column is locked — never allow dragging it.
          if (idx === 0) {
            return;
          }
          // Filler column is a layout-only column that must remain at the end.
          if (cell.classList.contains('filler-column')) {
            return;
          }
          // Skip resize handle, ⋮ menu trigger, and sort indicator —
          // those have their own click handlers. setPointerCapture must not
          // be called on these targets or the browser re-routes the click to
          // the <th> (the captured element), preventing their handlers from firing.
          const target = e.target as HTMLElement;
          if (
            target.closest('.oui-col-resize-handle') ||
            target.closest('.oui-column-menu-trigger') ||
            target.closest('.oui-column-sort-indicator')
          ) {
            return;
          }
          this._onPointerDown(e, cell, idx);
        }
      );
      this._cellUnlisteners.push(unlisten);
    });
  }

  private _detachCellListeners(): void {
    this._cellUnlisteners.forEach((fn) => fn());
    this._cellUnlisteners = [];
  }

  // ─── MutationObserver: re-attach after column re-render ──────────────────────

  private _watchHeaderRow(): void {
    const host = this._elementRef.nativeElement;
    // Observe the direct children of the table host; CDK re-stamps header cells
    // into the header row when displayedColumns changes.
    this._mutationObserver = new MutationObserver(() => {
      // Debounce: CDK may fire multiple mutations in one tick.
      // Skip re-attaching while a drag is active — it would tear down listeners
      // on the cell that currently holds pointer capture.
      if (this._dragActive) {
        return;
      }
      setTimeout(() => {
        if (!this._dragActive) {
          this._attachCellListeners();
        }
      }, 0);
    });
    this._mutationObserver.observe(host, { childList: true, subtree: true });
  }

  // ─── Drag lifecycle ───────────────────────────────────────────────────────────

  private _onPointerDown(
    e: PointerEvent,
    cell: HTMLElement,
    cellIndex: number
  ): void {
    this._dragging = false;
    this._dragActive = true;
    this._sourceIndex = cellIndex;
    this._startX = e.clientX;
    this._startY = e.clientY;

    // Capture cursor offset within the cell so the ghost stays pinned under the cursor.
    const cellRect = cell.getBoundingClientRect();
    this._cursorOffsetX = e.clientX - cellRect.left;
    this._cursorOffsetY = e.clientY - cellRect.top;

    // Snapshot column IDs now — they won't change mid-drag.
    this._columnIds = this._headerCells.map((c) => this._getColumnId(c));

    // Pointer capture: all subsequent pointermove / pointerup events are
    // delivered to `cell` regardless of where the pointer moves — same
    // pattern used by the resize directive.
    cell.setPointerCapture(e.pointerId);

    this._dragMoveUnlisten = this._renderer.listen(
      cell,
      'pointermove',
      (ev: PointerEvent) => this._onPointerMove(ev)
    );
    this._dragUpUnlisten = this._renderer.listen(
      cell,
      'pointerup',
      (ev: PointerEvent) => this._onPointerUp(ev)
    );
    this._dragCancelUnlisten = this._renderer.listen(
      cell,
      'pointercancel',
      () => this._cancelDrag()
    );
    // lostpointercapture fires whenever the browser releases capture for any reason
    // (long-hold OS gesture, context menu, native drag takeover, etc.).
    // Treat it as a cancel — ghost snaps back, no reorder emitted.
    this._dragLostCaptureUnlisten = this._renderer.listen(
      cell,
      'lostpointercapture',
      () => this._cancelDrag()
    );
    // Suppress text-selection during hold+drag — browsers fire selectstart on
    // long presses which can steal the pointer stream away from our handlers.
    this._dragSelectStartUnlisten = this._renderer.listen(
      cell,
      'selectstart',
      (ev: Event) => ev.preventDefault()
    );
    // Suppress native HTML5 drag — it fires 'dragstart' after a long hold and
    // can swallow the subsequent pointerup, leaving the ghost stranded.
    this._dragNativeDragUnlisten = this._renderer.listen(
      cell,
      'dragstart',
      (ev: Event) => ev.preventDefault()
    );

    // Document-level pointerup: guaranteed to fire regardless of pointer capture
    // state. This is the safety net that ensures highlights are always removed.
    this._removeDocPointerUp();
    this._docPointerUpHandler = (ev: PointerEvent) => this._onPointerUp(ev);
    document.addEventListener('pointerup', this._docPointerUpHandler, {
      once: true,
    });
  }

  private _onPointerMove(e: PointerEvent): void {
    this._lastClientX = e.clientX;
    this._lastClientY = e.clientY;

    const dx = e.clientX - this._startX;
    const dy = e.clientY - this._startY;

    if (!this._dragging) {
      // Wait for 5px movement before committing to a drag.
      if (Math.sqrt(dx * dx + dy * dy) < 5) {
        return;
      }
      this._dragging = true;
      this._createGhost();
      this._createDropIndicator();
      this._renderer.addClass(
        this._elementRef.nativeElement,
        'oui-table-reordering'
      );
      // Highlight only the source header cell (not the whole column).
      if (this._sourceIndex >= 0 && this._headerCells[this._sourceIndex]) {
        this._renderer.addClass(
          this._headerCells[this._sourceIndex],
          'oui-col-reorder-source'
        );
      }
    }

    // Ghost follows the cursor freely in both X and Y.
    // Only the height is pinned to the table height.
    if (this._ghost) {
      const tableRect = this._elementRef.nativeElement.getBoundingClientRect();
      const bounds = this._getVisibleBounds(tableRect);
      // Ghost follows the cursor freely in both X and Y —
      // only its height is locked to the visible table height.
      const ghostX = e.clientX - this._cursorOffsetX;
      const ghostY = e.clientY - this._cursorOffsetY;

      this._renderer.setStyle(
        this._ghost,
        'transform',
        `translate(${ghostX}px, ${ghostY}px)`
      );
      // Keep ghost height equal to the visible table height.
      this._renderer.setStyle(
        this._ghost,
        'height',
        `${bounds.bottom - bounds.top}px`
      );
    }

    this._insertionSlot = this._getInsertionSlot(e.clientX);
    const isOverTable = this._isCursorOverHeaderCell(e.clientX, e.clientY);
    this._positionDropIndicator(this._insertionSlot, isOverTable);

    // ── Auto-scroll ─────────────────────────────────────────────────────────
    // Check whether the cursor is near the scroll container's left or right
    // edge. If so, flag the RAF loop to keep scrolling; otherwise stop it.
    const scrollContainer = this._getScrollContainer();
    if (scrollContainer) {
      const sr = scrollContainer.getBoundingClientRect();
      const distLeft = e.clientX - sr.left;
      const distRight = sr.right - e.clientX;
      const nearEdge =
        (distLeft > 0 && distLeft < this._scrollZoneSize) ||
        (distRight > 0 && distRight < this._scrollZoneSize);
      if (nearEdge) {
        this._scrollContainer = scrollContainer;
        this._scrollWanted = true;
        this._startAutoScroll();
      } else {
        this._scrollWanted = false;
        // The RAF loop checks _scrollWanted on every frame and stops itself.
      }
    } else {
      this._scrollWanted = false;
    }
  }

  private _onPointerUp(_e: PointerEvent): void {
    // Guard: prevent double-entry (cell pointerup + document pointerup both fire)
    // and prevent lostpointercapture from re-entering cleanup.
    if (this._pointerUpInProgress || !this._dragActive) {
      return;
    }
    this._pointerUpInProgress = true;

    // Stop auto-scroll before any other cleanup.
    this._stopAutoScroll();

    const wasDragging = this._dragging;
    this._dragging = false;

    // Remove ALL drag listeners first so releasePointerCapture won't
    // trigger lostpointercapture → _cancelDrag.
    this._cleanupDragListeners();

    // Now safe to release pointer capture.
    if (this._sourceIndex >= 0 && this._headerCells[this._sourceIndex]) {
      try {
        this._headerCells[this._sourceIndex].releasePointerCapture(
          _e.pointerId
        );
      } catch {
        // Already released by the browser.
      }
    }

    // Always clean up ALL visual artifacts.
    this._clearAllHighlights();
    this._destroyGhost();
    this._destroyDropIndicator();
    this._renderer.removeClass(
      this._elementRef.nativeElement,
      'oui-table-reordering'
    );

    this._pointerUpInProgress = false;

    if (!wasDragging) {
      return;
    }

    // After a real drag, suppress the click event that the browser fires
    // immediately after pointerup. Without this, releasing the pointer
    // over the sort indicator fires onSortClick and triggers an unintended sort.
    // Use document-level capture to intercept regardless of which element
    // the click is dispatched to (varies by browser / capture state).
    const suppressDragClick = (evt: MouseEvent) => {
      evt.stopImmediatePropagation();
      evt.preventDefault();
    };
    document.addEventListener('click', suppressDragClick, {
      capture: true,
      once: true,
    });
    // Safety: remove the suppressor if no click fires within 300ms.
    setTimeout(
      () => document.removeEventListener('click', suppressDragClick, true),
      300
    );

    const prev = this._sourceIndex;

    // Valid drop: cursor is over a header cell and the insertion slot would
    // actually move the column (not a no-op).
    const isNoOp =
      this._insertionSlot === prev || this._insertionSlot === prev + 1;
    const validDrop =
      !isNoOp && this._isCursorOverHeaderCell(_e.clientX, _e.clientY);

    if (validDrop) {
      // Convert the insertion slot to a final index in the original array.
      // _insertionSlot is the slot index in the current column order.
      // When the source is before the slot, removing it shifts all later
      // indices down by one, so we subtract 1 from the slot.
      let finalIndex = this._insertionSlot;
      if (prev < finalIndex) {
        finalIndex -= 1;
      }
      // Clamp to valid range after removal.
      finalIndex = Math.max(
        0,
        Math.min(finalIndex, this._columnIds.length - 1)
      );

      if (prev !== finalIndex) {
        const newOrder = [...this._columnIds];
        const [moved] = newOrder.splice(prev, 1);
        newOrder.splice(finalIndex, 0, moved);

        this._ngZone.run(() => {
          this.columnOrderChanged.emit({
            previousIndex: prev,
            currentIndex: finalIndex,
            columnIds: newOrder,
          });
        });
      }
    }
  }

  private _cancelDrag(): void {
    // If _onPointerUp is already handling cleanup, do nothing.
    if (this._pointerUpInProgress) {
      return;
    }
    this._dragging = false;
    this._stopAutoScroll();
    this._cleanupDragListeners();
    // Always clean up visual artifacts — even if _dragging was not yet true
    // (e.g. lostpointercapture during a long hold).
    this._clearAllHighlights();
    this._destroyGhost();
    this._destroyDropIndicator();
    this._renderer.removeClass(
      this._elementRef.nativeElement,
      'oui-table-reordering'
    );
  }

  private _cleanupDragListeners(): void {
    this._dragMoveUnlisten?.();
    this._dragUpUnlisten?.();
    this._dragCancelUnlisten?.();
    this._dragLostCaptureUnlisten?.();
    this._dragSelectStartUnlisten?.();
    this._dragNativeDragUnlisten?.();
    this._dragMoveUnlisten = null;
    this._dragUpUnlisten = null;
    this._dragCancelUnlisten = null;
    this._dragLostCaptureUnlisten = null;
    this._dragSelectStartUnlisten = null;
    this._dragNativeDragUnlisten = null;
    this._removeDocPointerUp();
    this._stopAutoScroll();
    this._dragActive = false;
  }

  private _removeDocPointerUp(): void {
    if (this._docPointerUpHandler) {
      document.removeEventListener('pointerup', this._docPointerUpHandler);
      this._docPointerUpHandler = null;
    }
  }

  // ─── Helpers ──────────────────────────────────────────────────────────────────

  /**
   * Returns the visible bounds of the table, intersected with the nearest
   * scroll ancestor AND the viewport so drag visuals never escape the
   * visible area — even when the page itself is the scroll context.
   */
  private _getVisibleBounds(tableRect: DOMRect): {
    left: number;
    top: number;
    right: number;
    bottom: number;
  } {
    const bounds = {
      left: tableRect.left,
      top: tableRect.top,
      right: tableRect.right,
      bottom: tableRect.bottom,
    };

    // Walk up to find the nearest scroll ancestor and clamp to its rect.
    const scrollParent = this._findScrollParent(this._elementRef.nativeElement);
    if (scrollParent) {
      const sr = scrollParent.getBoundingClientRect();
      bounds.left = Math.max(bounds.left, sr.left);
      bounds.top = Math.max(bounds.top, sr.top);
      bounds.right = Math.min(bounds.right, sr.right);
      bounds.bottom = Math.min(bounds.bottom, sr.bottom);
    }

    // Always clamp to the viewport as a final safety net (handles
    // page-level scrolling where no scroll ancestor exists).
    bounds.left = Math.max(bounds.left, 0);
    bounds.top = Math.max(bounds.top, 0);
    bounds.right = Math.min(bounds.right, globalThis.innerWidth);
    bounds.bottom = Math.min(bounds.bottom, globalThis.innerHeight);

    return bounds;
  }

  /** Walk up the DOM to find the nearest ancestor with overflow scrolling. */
  private _findScrollParent(el: HTMLElement): HTMLElement | null {
    let parent = el.parentElement;
    while (parent && parent !== document.documentElement) {
      const style = globalThis.getComputedStyle(parent);
      if (/(auto|scroll|hidden)/.test(style.overflowY)) {
        return parent;
      }
      parent = parent.parentElement;
    }
    return null;
  }

  private _getColumnId(cell: HTMLElement): string {
    const cls = Array.from(cell.classList).find((c) =>
      c.startsWith('cdk-column-')
    );
    return cls ? cls.replace('cdk-column-', '') : '';
  }

  /** Returns true if the cursor is within any header cell's bounding rect. */
  private _isCursorOverHeaderCell(clientX: number, clientY: number): boolean {
    return this._headerCells.some((cell) => {
      const r = cell.getBoundingClientRect();
      return (
        clientX >= r.left &&
        clientX <= r.right &&
        clientY >= r.top &&
        clientY <= r.bottom
      );
    });
  }

  /**
   * Calculate the insertion slot index — the position BEFORE which the
   * dragged column will be inserted. This is edge-based, not center-based:
   * the cursor position relative to each column boundary determines the slot.
   *
   * Returns a value in [1, _headerCells.length] (slot 0 = before the locked
   * first column, which is never valid).
   */
  private _getInsertionSlot(clientX: number): number {
    const tableRect = this._elementRef.nativeElement.getBoundingClientRect();
    const bounds = this._getVisibleBounds(tableRect);
    const clampedX = Math.max(bounds.left, Math.min(clientX, bounds.right));

    // The last valid slot index.  When a filler column exists the slot range
    // ends before it (no drops past / on the filler column).
    const hasFiller = this._hasFillerColumn();
    const end = hasFiller
      ? this._headerCells.length - 1
      : this._headerCells.length;

    // Walk the header cells and find which gap the cursor falls into.
    // A "gap" is between the midpoint of column N and the midpoint of column N+1.
    // If cursor is left of the first movable column's midpoint → slot = 1.
    // If cursor is right of the last valid column's midpoint → slot = end.
    for (let i = 1; i < end; i++) {
      const rect = this._headerCells[i].getBoundingClientRect();
      const mid = rect.left + rect.width / 2;
      if (clampedX < mid) {
        return i;
      }
    }
    return end;
  }

  // ─── Ghost ────────────────────────────────────────────────────────────────────

  private _createGhost(): void {
    const source = this._headerCells[this._sourceIndex];
    const cellRect = source.getBoundingClientRect();
    const tableRect = this._elementRef.nativeElement.getBoundingClientRect();
    const bounds = this._getVisibleBounds(tableRect);

    this._ghost = this._renderer.createElement('div') as HTMLElement;
    this._renderer.addClass(this._ghost, 'oui-col-reorder-ghost');
    // Full column size: same width as source header, height clipped to visible table area.
    this._renderer.setStyle(this._ghost, 'width', `${cellRect.width}px`);
    this._renderer.setStyle(
      this._ghost,
      'height',
      `${bounds.bottom - bounds.top}px`
    );
    // Start at source column, top of visible table area.
    this._renderer.setStyle(
      this._ghost,
      'transform',
      `translate(${cellRect.left}px, ${bounds.top}px)`
    );
    this._renderer.appendChild(document.body, this._ghost);
  }

  private _destroyGhost(): void {
    if (this._ghost) {
      this._ghost.remove();
      this._ghost = null;
    }
  }

  // ─── Drop indicator ───────────────────────────────────────────────────────────

  private _createDropIndicator(): void {
    this._dropIndicator = this._renderer.createElement('div') as HTMLElement;
    this._renderer.addClass(this._dropIndicator, 'oui-col-reorder-indicator');
    this._renderer.appendChild(document.body, this._dropIndicator);
  }

  /**
   * Position the drop indicator at the insertion slot boundary.
   * The slot index points BEFORE a column, so we use the left edge of
   * that column — or the right edge of the last column for the end slot.
   */
  private _positionDropIndicator(slot: number, visible: boolean): void {
    if (!this._dropIndicator) {
      return;
    }
    // Hide when cursor is outside the table header area, or when the
    // insertion slot equals the source (no-op drop).
    // Also hide the left edge of the first column (slot <= 0).
    // When a filler column is present, also hide the right edge of the
    // filler column (slot >= headerCells.length) — no drops beyond it.
    // Without a filler column, slot == headerCells.length is a valid
    // "insert after the last column" position.
    const hasFiller = this._hasFillerColumn();
    const isNoOp = slot === this._sourceIndex || slot === this._sourceIndex + 1;
    const isEdge = slot <= 0 || (hasFiller && slot >= this._headerCells.length);
    if (!visible || isNoOp || isEdge) {
      this._renderer.setStyle(this._dropIndicator, 'display', 'none');
      return;
    }
    this._renderer.setStyle(this._dropIndicator, 'display', '');

    const tableRect = this._elementRef.nativeElement.getBoundingClientRect();
    const bounds = this._getVisibleBounds(tableRect);
    const indicatorWidth = 2;

    let rawX: number;
    if (slot >= this._headerCells.length) {
      // Insert at the very end — use right edge of last column.
      const lastCell = this._headerCells[this._headerCells.length - 1];
      rawX = lastCell.getBoundingClientRect().right;
    } else {
      // Insert before column at `slot` — use its left edge.
      rawX = this._headerCells[slot].getBoundingClientRect().left;
    }

    // Clamp to visible bounds so the indicator never renders outside the
    // table's visible area.
    const xPos = Math.max(
      bounds.left,
      Math.min(rawX, bounds.right - indicatorWidth)
    );

    // Never show the drop indicator at or within the sticky first column's
    // area — it would appear clipped behind or peeking through the sticky
    // overlay.  We check the *rendered* position xPos because the clamp
    // to bounds.left can pull a far-left column edge into the first
    // column's visual space.
    const firstRect = this._headerCells[0].getBoundingClientRect();
    if (slot === 1 || xPos <= firstRect.right) {
      this._renderer.setStyle(this._dropIndicator, 'display', 'none');
      return;
    }

    this._renderer.setStyle(
      this._dropIndicator,
      'transform',
      `translate(${xPos}px, ${bounds.top}px)`
    );
    this._renderer.setStyle(
      this._dropIndicator,
      'height',
      `${bounds.bottom - bounds.top}px`
    );
  }

  private _destroyDropIndicator(): void {
    if (this._dropIndicator) {
      this._renderer.removeChild(document.body, this._dropIndicator);
      this._dropIndicator = null;
    }
  }

  // ─── Auto-scroll ─────────────────────────────────────────────────────────────

  /**
   * Walk up the DOM to find the nearest horizontally-scrollable ancestor
   * that currently overflows — this is the container we'll auto-scroll.
   */
  private _getScrollContainer(): HTMLElement | null {
    const isScrollable = (el: HTMLElement): boolean => {
      const ox = globalThis.getComputedStyle(el).overflowX;
      return (
        (ox === 'auto' || ox === 'scroll') && el.scrollWidth > el.clientWidth
      );
    };

    // First pass: walk up the parent chain.
    let el: HTMLElement | null = this._elementRef.nativeElement.parentElement;
    while (el && el !== document.documentElement) {
      if (isScrollable(el)) {
        return el;
      }
      el = el.parentElement;
    }

    // Fallback: check the table element itself.
    if (isScrollable(this._elementRef.nativeElement)) {
      return this._elementRef.nativeElement;
    }

    // Last resort: the body element (page-level scroll).
    if (isScrollable(document.body)) {
      return document.body;
    }

    return null;
  }

  /**
   * Start (or restart) the auto-scroll RAF loop.
   * The loop only keeps running while `_scrollWanted` is true.
   */
  private _startAutoScroll(): void {
    if (this._scrollRafId || !this._dragging || !this._scrollContainer) {
      return;
    }
    this._scrollRafId = requestAnimationFrame(this._scrollLoop);
  }

  /** Single requestAnimationFrame step — scrolls then re-queues if needed. */
  private _scrollLoop = (): void => {
    // Stop when the drag ended, the container disappeared, or the cursor
    // is no longer near the edge (set in _onPointerMove).
    if (!this._dragging || !this._scrollContainer || !this._scrollWanted) {
      this._stopAutoScroll();
      return;
    }

    const rect = this._scrollContainer.getBoundingClientRect();
    const distLeft = this._lastClientX - rect.left;
    const distRight = rect.right - this._lastClientX;

    let scrollDelta = 0;
    if (distLeft > 0 && distLeft < this._scrollZoneSize) {
      const factor = 1 - distLeft / this._scrollZoneSize;
      scrollDelta = -Math.round(factor * this._scrollMaxSpeed);
    } else if (distRight > 0 && distRight < this._scrollZoneSize) {
      const factor = 1 - distRight / this._scrollZoneSize;
      scrollDelta = Math.round(factor * this._scrollMaxSpeed);
    }

    if (scrollDelta !== 0) {
      this._scrollContainer.scrollLeft += scrollDelta;
    }

    // Always recalculate the insertion slot and indicator on every RAF
    // frame — even when scrollDelta is 0 — so the indicator tracks
    // column boundaries smoothly as they shift during scroll.
    this._insertionSlot = this._getInsertionSlot(this._lastClientX);
    const isOverTable = this._isCursorOverHeaderCell(
      this._lastClientX,
      this._lastClientY
    );
    this._positionDropIndicator(this._insertionSlot, isOverTable);

    // Re-queue — the _scrollWanted guard at the top will stop the loop
    // on the next frame if the cursor has left the activation zone.
    this._scrollRafId = requestAnimationFrame(this._scrollLoop);
  };

  /** Cancel the auto-scroll animation frame. */
  private _stopAutoScroll(): void {
    if (this._scrollRafId) {
      cancelAnimationFrame(this._scrollRafId);
      this._scrollRafId = 0;
    }
    this._scrollContainer = null;
    this._scrollWanted = false;
  }

  // ─── Column highlight helpers ─────────────────────────────────────────────────────────────────

  /** Returns true when the last header cell carries the `filler-column` class. */
  private _hasFillerColumn(): boolean {
    const cells = this._headerCells;
    return (
      cells.length > 0 && cells.at(-1)!.classList.contains('filler-column')
    );
  }

  /** Add or remove a CSS class on every cell (header + body) in the given column. */
  private _applyColumnClass(columnId: string, cls: string, add: boolean): void {
    if (!columnId) {
      return;
    }
    this._elementRef.nativeElement
      .querySelectorAll<HTMLElement>(`.cdk-column-${columnId}`)
      .forEach((cell) =>
        add
          ? this._renderer.addClass(cell, cls)
          : this._renderer.removeClass(cell, cls)
      );
  }

  /** Remove all drag-related highlight classes from the table. */
  private _clearAllHighlights(): void {
    // Clear via tracked state (fast path).
    if (this._highlightedTargetColumnId) {
      this._applyColumnClass(
        this._highlightedTargetColumnId,
        'oui-col-reorder-target',
        false
      );
      this._highlightedTargetColumnId = '';
    }
    // Source highlight is only on the header cell.
    if (this._sourceIndex >= 0 && this._headerCells[this._sourceIndex]) {
      this._headerCells[this._sourceIndex].classList.remove(
        'oui-col-reorder-source'
      );
    }

    // Safety-net: sweep the ENTIRE table for any stale highlight classes.
    // Use direct classList instead of Renderer2 to guarantee synchronous removal.
    this._elementRef.nativeElement
      .querySelectorAll('.oui-col-reorder-source, .oui-col-reorder-target')
      .forEach((el: Element) => {
        el.classList.remove('oui-col-reorder-source');
        el.classList.remove('oui-col-reorder-target');
      });

    // Also sweep document.body for any ghost/indicator elements that may have leaked.
    document
      .querySelectorAll('.oui-col-reorder-ghost, .oui-col-reorder-indicator')
      .forEach((el) => el.remove());
    this._ghost = null;
    this._dropIndicator = null;
  }

  // ─── Cleanup ──────────────────────────────────────────────────────────────────────────────

  // ─── Overflow detection ──────────────────────────────────────────────────────

  private _watchOverflow(): void {
    const tableEl = this._elementRef.nativeElement;
    const container = tableEl.parentElement;
    if (!container) {
      return;
    }

    const update = () => {
      const overflows = container.scrollWidth > container.clientWidth;
      if (overflows) {
        this._renderer.addClass(tableEl, 'oui-table-col-overflow');
      } else {
        this._renderer.removeClass(tableEl, 'oui-table-col-overflow');
      }
    };

    this._overflowObserver = new ResizeObserver(update);
    this._overflowObserver.observe(container);
    this._overflowObserver.observe(tableEl);
    update();
  }

  ngOnDestroy(): void {
    this._detachCellListeners();
    this._clearAllHighlights();
    this._cleanupDragListeners();
    this._mutationObserver?.disconnect();
    this._overflowObserver?.disconnect();
    this._overflowObserver = null;
    this._destroyGhost();
    this._destroyDropIndicator();
  }
}

import {
  AfterViewInit,
  Directive,
  DoCheck,
  ElementRef,
  EventEmitter,
  inject,
  Input,
  NgZone,
  OnDestroy,
  Output,
  Renderer2,
  RendererStyleFlags2,
} from '@angular/core';
import { ColumnResizeEvent } from './oui-column-resize.directive';

/**
 * Makes a single table header cell resizable by dragging its right edge.
 *
 * This directive is intentionally scoped to exactly ONE column: it only ever
 * reads/writes the width of the cells that belong to its own column (the
 * header cell it's attached to, plus every body cell sharing the same
 * `cdk-column-<id>` class within the closest ancestor `<table>`). It never
 * inspects or mutates any other column's state, and it holds no cross-column
 * bookkeeping (no shared width map, no MutationObserver watching the whole
 * table for column add/remove/reorder).
 *
 * This is the key difference from `OuiResizableColumnsDirective` (table-wide
 * `ouiResizableColumns`), which has to track every column's width centrally
 * and reconcile that state whenever columns are added, removed, or
 * reordered — the source of most of the flakiness this directive avoids.
 * Because each column instance manages only itself, and Angular
 * creates/destroys one directive instance per header cell as columns come
 * and go (`*ouiHeaderCellDef`), adding or removing sibling columns (e.g. via
 * a column-visibility picker) has zero effect on this directive; there is
 * nothing to reconcile.
 *
 * Usage — add directly to the header cell for a column:
 * ```html
 * <th
 *   oui-header-cell
 *   ouiResizableColumn
 *   [columnId]="col.key"
 *   [minWidth]="140"
 *   [width]="columnWidths[col.key]"
 *   (columnResized)="onColumnResized($event)"
 * >
 * ```
 */
@Directive({
  selector:
    'th[oui-header-cell][ouiResizableColumn], oui-header-cell[ouiResizableColumn]',
  standalone: false,
})
export class OuiResizableColumnDirective
  implements AfterViewInit, DoCheck, OnDestroy
{
  /**
   * CDK column id for this header cell. Optional — when omitted it is
   * auto-detected from the host's `cdk-column-<id>` class.
   */
  @Input() columnId = '';

  /** Minimum width (px) this column can be resized to. */
  @Input() minWidth = 100;

  /**
   * Initial width (px) to apply once, when the handle is first created —
   * e.g. a previously persisted width restored after a page refresh. Ignored
   * (falls back to the column's natural/CSS width) when omitted or <= 0.
   */
  @Input() width?: number;

  /** Emitted once the user releases the pointer after actually resizing this column. */
  @Output() columnResized = new EventEmitter<ColumnResizeEvent>();

  private readonly _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly _renderer = inject(Renderer2);
  private readonly _ngZone = inject(NgZone);

  private _handle: HTMLElement | null = null;
  private _handlePointerDownUnlisten: (() => void) | null = null;
  private _moveUnlisten: (() => void) | null = null;
  private _upUnlisten: (() => void) | null = null;
  private _cancelUnlisten: (() => void) | null = null;

  private _isDragging = false;
  /** True once the pointer has actually moved during the current drag (delta > 2px). */
  private _hasMoved = false;
  private _startX = 0;
  private _startWidth = 0;
  /** Minimum width the column may reach (content + padding, measured at drag-start). */
  private _minCellWidth = 0;
  /** Header + body cells belonging to this column (scoped to the closest ancestor table). */
  private _columnCells: HTMLElement[] = [];
  /**
   * Last width (px) we explicitly applied — either the restored/persisted
   * `width` or the result of a completed drag. Re-asserted on every
   * `ngDoCheck` (see below) so the column keeps its size even when something
   * outside this directive's control (e.g. the table re-rendering its rows
   * when the user sorts) recreates the column's cells without destroying
   * this directive instance, which would otherwise silently drop back to
   * the CSS baseline/content-based width. `null` means this column was never
   * explicitly sized and should keep using its natural/CSS width.
   */
  private _lastAppliedWidth: number | null = null;

  ngAfterViewInit(): void {
    this._ngZone.runOutsideAngular(() => {
      this._createHandle();
    });
  }

  /**
   * Cheap self-healing check: if this column has an explicitly-applied width
   * and isn't mid-drag, re-assert it on whatever cells currently match this
   * column. This makes the applied width resilient to external re-renders
   * (e.g. CDK Table rebuilding rows on sort) that don't tear down this
   * directive instance — those would otherwise leave freshly-rendered cells
   * without our inline width, silently falling back to auto/content-based
   * sizing. Re-querying `_getColumnCells` fresh (rather than relying on a
   * cached list) also picks up any newly-created cells for this column.
   *
   * The (cheap) `getBoundingClientRect` read lets every no-drift check cycle
   * — the overwhelming majority — bail out after a single layout read,
   * instead of always re-querying and re-styling every matching cell.
   */
  ngDoCheck(): void {
    if (this._isDragging || this._lastAppliedWidth === null) {
      return;
    }
    const host = this._elementRef.nativeElement;
    const currentWidth = host.getBoundingClientRect().width;
    if (Math.abs(currentWidth - this._lastAppliedWidth) <= 1) {
      return;
    }
    this._ngZone.runOutsideAngular(() => {
      this._setCellsWidth(this._lastAppliedWidth!, this._getColumnCells(host));
    });
  }

  ngOnDestroy(): void {
    this._removeDragListeners();
    this._handlePointerDownUnlisten?.();
    this._handle?.remove();
    this._handle = null;
  }

  private _createHandle(): void {
    const host = this._elementRef.nativeElement;
    if (!this.columnId) {
      this.columnId = this._detectColumnId(host);
    }

    this._renderer.setStyle(host, 'position', 'relative');
    this._renderer.setStyle(host, 'overflow', 'visible');

    // Restore a previously persisted width, if one was provided.
    if (this.width && this.width > 0) {
      const table = host.closest('table');
      if (table) {
        this._renderer.setStyle(
          table,
          'table-layout',
          'fixed',
          RendererStyleFlags2.Important
        );
      }
      this._setCellsWidth(this.width, this._getColumnCells(host));
    }

    const handle = this._renderer.createElement('div') as HTMLElement;
    this._renderer.addClass(handle, 'oui-col-resize-handle');
    this._renderer.setAttribute(handle, 'aria-hidden', 'true');
    this._renderer.setStyle(handle, 'touch-action', 'none');
    this._renderer.setStyle(handle, 'cursor', 'col-resize');
    this._renderer.appendChild(host, handle);
    this._handle = handle;

    this._handlePointerDownUnlisten = this._renderer.listen(
      handle,
      'pointerdown',
      (e: PointerEvent) => {
        e.preventDefault();
        e.stopPropagation();
        this._onPointerDown(e, host, handle);
      }
    );
  }

  private _detectColumnId(cell: HTMLElement): string {
    const colClass = Array.from(cell.classList).find((c) =>
      c.startsWith('cdk-column-')
    );
    return colClass ? colClass.replace('cdk-column-', '') : '';
  }

  private _getColumnCells(host: HTMLElement): HTMLElement[] {
    if (!this.columnId) {
      return [host];
    }
    const table = host.closest('table');
    const scope: ParentNode = table ?? host.ownerDocument;
    return Array.from(
      scope.querySelectorAll<HTMLElement>(`.cdk-column-${this.columnId}`)
    );
  }

  private _onPointerDown(
    e: PointerEvent,
    host: HTMLElement,
    handle: HTMLElement
  ): void {
    this._isDragging = true;
    this._hasMoved = false;
    this._startX = e.clientX;
    this._startWidth = host.getBoundingClientRect().width;
    this._columnCells = this._getColumnCells(host);

    // Fixed layout keeps pixel widths from being fought by the browser's
    // auto-layout algorithm. Idempotent — harmless to set on every drag.
    const table = host.closest('table');
    if (table) {
      this._renderer.setStyle(
        table,
        'table-layout',
        'fixed',
        RendererStyleFlags2.Important
      );
    }

    this._minCellWidth = this.minWidth;

    try {
      handle.setPointerCapture(e.pointerId);
    } catch {
      // Pointer capture can fail in browsers without full support; drag still
      // works because listeners are attached directly to the handle.
    }

    this._renderer.addClass(handle, 'oui-col-resize-handle--active');
    this._renderer.addClass(host.ownerDocument.body, 'oui-table-resize-cursor');
    this._columnCells.forEach((cell) =>
      this._renderer.addClass(cell, 'oui-col-resize-active')
    );

    this._moveUnlisten = this._renderer.listen(
      handle,
      'pointermove',
      (ev: PointerEvent) => this._onPointerMove(ev)
    );
    this._upUnlisten = this._renderer.listen(
      handle,
      'pointerup',
      (ev: PointerEvent) => this._onPointerUp(ev, host)
    );
    this._cancelUnlisten = this._renderer.listen(handle, 'pointercancel', () =>
      this._onPointerCancel(host)
    );
  }

  private _onPointerMove(e: PointerEvent): void {
    if (!this._isDragging) {
      return;
    }
    const delta = e.clientX - this._startX;
    if (Math.abs(delta) > 2) {
      this._hasMoved = true;
    }
    const newWidth = Math.max(this._minCellWidth, this._startWidth + delta);
    this._applyWidth(newWidth);
  }

  private _onPointerUp(_e: PointerEvent, host: HTMLElement): void {
    if (!this._isDragging) {
      return;
    }
    const hasMoved = this._hasMoved;
    this._isDragging = false;
    this._hasMoved = false;
    this._removeDragListeners();
    this._endDragVisuals(host);

    if (!hasMoved) {
      return;
    }

    // Swallow the click the browser fires right after pointerup so it
    // doesn't land on the sort-header button and trigger an unwanted sort.
    const suppressClick = (ev: MouseEvent) => ev.stopPropagation();
    host.addEventListener('click', suppressClick, {
      capture: true,
      once: true,
    });
    setTimeout(
      () => host.removeEventListener('click', suppressClick, true),
      300
    );

    const finalWidth =
      this._columnCells[0]?.getBoundingClientRect().width ?? this._startWidth;
    this._applyWidth(finalWidth);
    this._lastAppliedWidth = finalWidth;

    this._ngZone.run(() => {
      this.columnResized.emit({ columnId: this.columnId, width: finalWidth });
    });
  }

  private _onPointerCancel(host: HTMLElement): void {
    if (!this._isDragging) {
      return;
    }
    this._isDragging = false;
    this._hasMoved = false;
    this._removeDragListeners();
    this._endDragVisuals(host);
    // Roll back to the pre-drag width.
    this._applyWidth(this._startWidth);
    this._lastAppliedWidth = this._startWidth;
  }

  private _endDragVisuals(host: HTMLElement): void {
    this._renderer.removeClass(
      host.ownerDocument.body,
      'oui-table-resize-cursor'
    );
    if (this._handle) {
      this._renderer.removeClass(this._handle, 'oui-col-resize-handle--active');
    }
    this._columnCells.forEach((cell) =>
      this._renderer.removeClass(cell, 'oui-col-resize-active')
    );
  }

  private _applyWidth(width: number): void {
    this._setCellsWidth(width, this._columnCells);
  }

  private _setCellsWidth(width: number, cells: HTMLElement[]): void {
    const px = `${width}px`;
    cells.forEach((cell) => {
      this._renderer.setStyle(cell, 'width', px, RendererStyleFlags2.Important);
      this._renderer.setStyle(
        cell,
        'min-width',
        px,
        RendererStyleFlags2.Important
      );
      this._renderer.setStyle(
        cell,
        'max-width',
        px,
        RendererStyleFlags2.Important
      );
      this._renderer.setStyle(cell, 'box-sizing', 'border-box');
    });
  }

  private _removeDragListeners(): void {
    this._moveUnlisten?.();
    this._upUnlisten?.();
    this._cancelUnlisten?.();
    this._moveUnlisten = null;
    this._upUnlisten = null;
    this._cancelUnlisten = null;
  }
}

import {
  AfterViewInit,
  Directive,
  ElementRef,
  EventEmitter,
  inject,
  Input,
  NgZone,
  OnDestroy,
  Output,
  PLATFORM_ID,
  Renderer2,
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

export interface ColumnResizeEvent {
  /** CDK column name (value of ouiColumnDef). */
  columnId: string;
  /** New column width in pixels. */
  width: number;
}

/**
 * @deprecated Use `ouiResizableColumn` on individual header cells instead. This directive will be removed in a future release.
 */
@Directive({
  selector:
    'oui-table[ouiResizableColumns], table[oui-table][ouiResizableColumns]',
  standalone: false,
})
export class OuiResizableColumnsDirective implements AfterViewInit, OnDestroy {
  /**
   * Minimum column width in pixels. Must be a positive number; if 0 or negative
   * the directive falls back to 200px.
   */
  @Input() minColumnWidth = 0;

  /**
