import { ComponentPortal, ComponentType, Portal } from '@angular/cdk/portal';
import {
  AfterContentInit,
  AfterViewChecked,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  Output,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { Subject, Subscription } from 'rxjs';
import { createMissingDateImplError } from './datepicker-errors';
import { OuiDatepickerIntl } from './datepicker-intl';
import { OuiMonthView } from './month-view';
import { OuiMultiYearView, yearsPerPage } from './multi-year-view';
import { OuiYearView } from './year-view';
import { OuiCalendarCellCssClasses } from './calendar-body';
import { DateAdapter } from './date-adapter';
import { OuiDateFormats, OUI_DATE_FORMATS } from './date-formats';
import { OuiIconRegistry } from '../icon/icon-registery';
import { DomSanitizer } from '@angular/platform-browser';
import { ICONS } from '../core/shared/icons';

/**
 * Possible views for the calendar.
 */
export type OuiCalendarView = 'month' | 'year' | 'multi-year';

/**
 * A calendar that is used as part of the datepicker.
 */
@Component({
  selector: 'oui-calendar',
  templateUrl: 'calendar.html',
  styleUrls: ['calendar.scss'],
  host: {
    class: 'oui-calendar',
  },
  exportAs: 'ouiCalendar',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: false,
})
export class OuiCalendar<D>
  implements AfterContentInit, AfterViewChecked, OnDestroy, OnChanges
{
  private _dateAdapter = inject<DateAdapter<D>>(DateAdapter, {
    optional: true,
  })!;
  private _dateFormats = inject<OuiDateFormats>(OUI_DATE_FORMATS, {
    optional: true,
  })!;
  private _changeDetectorRef = inject(ChangeDetectorRef);

  /** An input indicating the type of the header component, if set. */
  @Input() headerComponent: ComponentType<any>;

  /** A portal containing the header component type for this calendar. */
  _calendarHeaderPortal: Portal<any>;

  private _intlChanges: Subscription;

  /**
   * Used for scheduling that focus should be moved to the active cell on the next tick.
   * We need to schedule it, rather than do it immediately, because we have to wait
   * for Angular to re-evaluate the view children.
   */
  private _moveFocusOnNextTick = false;

  /** A date representing the period (month or year) to start the calendar in. */
  @Input()
  get startAt(): D | null {
    return this._startAt;
  }
  set startAt(value: D | null) {
    this._startAt = this._getValidDateOrNull(
      this._dateAdapter.deserialize(value)
    );
  }
  private _startAt: D | null;

  /** Whether the calendar should be started in month or year view. */
  @Input() startView: OuiCalendarView = 'month';

  /** The currently selected date. */
  @Input()
  get selected(): D | null {
    return this._selected;
  }
  set selected(value: D | null) {
    this._selected = this._getValidDateOrNull(
      this._dateAdapter.deserialize(value)
    );
  }
  private _selected: D | null;

  /** The minimum selectable date. */
  @Input()
  get minDate(): D | null {
    return this._minDate;
  }
  set minDate(value: D | null) {
    this._minDate = this._getValidDateOrNull(
      this._dateAdapter.deserialize(value)
    );
  }
  private _minDate: D | null;

  /** The maximum selectable date. */
  @Input()
  get maxDate(): D | null {
    return this._maxDate;
  }
  set maxDate(value: D | null) {
    this._maxDate = this._getValidDateOrNull(
      this._dateAdapter.deserialize(value)
    );
  }
  private _maxDate: D | null;

  /** Function used to filter which dates are selectable. */
  @Input() dateFilter: (date: D) => boolean;

  /** Function that can be used to add custom CSS classes to dates. */
  @Input() dateClass: (date: D) => OuiCalendarCellCssClasses;

  /** Emits when the currently selected date changes. */
  @Output() readonly selectedChange: EventEmitter<D> = new EventEmitter<D>();

  /**
   * Emits the year chosen in multiyear view.
   * This doesn't imply a change on the selected date.
   */
  @Output() readonly yearSelected: EventEmitter<D> = new EventEmitter<D>();

  /**
   * Emits the month chosen in year view.
   * This doesn't imply a change on the selected date.
   */
  @Output() readonly monthSelected: EventEmitter<D> = new EventEmitter<D>();

  /** Emits when any date is selected. */
  @Output()
  readonly _userSelection: EventEmitter<void> = new EventEmitter<void>();

  /** Reference to the current month view component. */
  @ViewChild(OuiMonthView) monthView: OuiMonthView<D>;

  /** Reference to the current year view component. */
  @ViewChild(OuiYearView) yearView: OuiYearView<D>;

  /** Reference to the current multi-year view component. */
  @ViewChild(OuiMultiYearView)
  multiYearView: OuiMultiYearView<D>;

  /**
   * The current active date. This determines which time period is shown and which date is
   * highlighted when using keyboard navigation.
   */
  get activeDate(): D {
    return this._clampedActiveDate;
  }
  set activeDate(value: D) {
    this._clampedActiveDate = this._dateAdapter.clampDate(
      value,
      this.minDate,
      this.maxDate
    );
    this.stateChanges.next();
  }
  private _clampedActiveDate: D;

  /** Whether the calendar is in month view. */
  get currentView(): OuiCalendarView {
    return this._currentView;
  }
  set currentView(value: OuiCalendarView) {
    this._currentView = value;
    this._moveFocusOnNextTick = true;
  }
  private _currentView: OuiCalendarView;

  /**
   * Emits whenever there is a state change that the header may need to respond to.
   */
  stateChanges = new Subject<void>();

  constructor() {
    const _intl = inject(OuiDatepickerIntl);
    const _changeDetectorRef = this._changeDetectorRef;

    if (!this._dateAdapter) {
      throw createMissingDateImplError('DateAdapter');
    }

    if (!this._dateFormats) {
      throw createMissingDateImplError('OuiDATE_FORMATS');
    }

    this._intlChanges = _intl.changes.subscribe(() => {
      _changeDetectorRef.markForCheck();
      this.stateChanges.next();
    });
  }

  ngAfterContentInit() {
    this._calendarHeaderPortal = new ComponentPortal(
      this.headerComponent || OuiCalendarHeader
    );
    this.activeDate = this.startAt || this._dateAdapter.today();

    // Assign to the private property since we don't want to move focus on init.
    this._currentView = this.startView;
  }

  ngAfterViewChecked() {
    if (this._moveFocusOnNextTick) {
      this._moveFocusOnNextTick = false;
      this.focusActiveCell();
    }
  }

  ngOnDestroy() {
    this._intlChanges.unsubscribe();
    this.stateChanges.complete();
  }

  ngOnChanges(changes: SimpleChanges) {
    const change = changes.minDate || changes.maxDate || changes.dateFilter;

    if (change && !change.firstChange) {
      const view = this._getCurrentViewComponent();

      if (view) {
        // We need to `detectChanges` manually here, because the `minDate`, `maxDate` etc. are
        // passed down to the view via data bindings which won't be up-to-date when we call `_init`.
        this._changeDetectorRef.detectChanges();
        view._init();
      }
    }

    this.stateChanges.next();
  }

  focusActiveCell() {
    this._getCurrentViewComponent()._focusActiveCell();
  }

  /** Updates today's date after an update of the active date */
  updateTodaysDate() {
    const view =
      this.currentView === 'month'
        ? this.monthView
        : this.currentView === 'year'
        ? this.yearView
        : this.multiYearView;

    view.ngAfterContentInit();
  }

  /** Handles date selection in the month view. */
  _dateSelected(date: D): void {
    if (!this._dateAdapter.sameDate(date, this.selected)) {
      this.selectedChange.emit(date);
    }
  }

  /** Handles year selection in the multiyear view. */
  _yearSelectedInMultiYearView(normalizedYear: D) {
    this.yearSelected.emit(normalizedYear);
  }

  /** Handles month selection in the year view. */
  _monthSelectedInYearView(normalizedMonth: D) {
    this.monthSelected.emit(normalizedMonth);
  }

  _userSelected(): void {
    this._userSelection.emit();
  }

  /** Handles year/month selection in the multi-year/year views. */
  _goToDateInView(date: D, view: 'month' | 'year' | 'multi-year'): void {
    this.activeDate = date;
    this.currentView = view;
  }

  /**
   * @param obj The object to check.
   * @returns The given object if it is both a date instance and valid, otherwise null.
   */
  private _getValidDateOrNull(obj: any): D | null {
    return this._dateAdapter.isDateInstance(obj) &&
      this._dateAdapter.isValid(obj as any as D)
      ? obj
      : null;
  }

  /** Returns the component instance that corresponds to the current calendar view. */
  private _getCurrentViewComponent() {
    return this.monthView || this.yearView || this.multiYearView;
  }
}

/** Default header for OuiCalendar */
@Component({
  selector: 'oui-calendar-header',
  templateUrl: 'calendar-header.html',
  exportAs: 'ouiCalendarHeader',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: false,
})
export class OuiCalendarHeader<D> {
  private _intl = inject(OuiDatepickerIntl);
  calendar = inject<OuiCalendar<D>>(OuiCalendar);
  private _dateAdapter = inject<DateAdapter<D>>(DateAdapter, {
    optional: true,
  })!;
  private ouiIconRegistry = inject(OuiIconRegistry);
  private domSanitizer = inject(DomSanitizer);

  constructor() {
    const changeDetectorRef = inject(ChangeDetectorRef);

    this.calendar.stateChanges.subscribe(() =>
      changeDetectorRef.markForCheck()
    );
    this.ouiIconRegistry.addSvgIconLiteral(
      `arrow-icon`,
      this.domSanitizer.bypassSecurityTrustHtml(ICONS.ARROW_ICON)
    );
  }

  /** The label for the current calendar view. */
  get periodButtonText(): string {
    if (this.calendar.currentView === 'month') {
      return (
        this._dateAdapter.getMonthNames('short')[
          this._dateAdapter.getMonth(this.calendar.activeDate)
        ] +
        ' ' +
        this._dateAdapter.getYearName(this.calendar.activeDate)
      );
    }
    if (this.calendar.currentView === 'year') {
      return this._dateAdapter.getYearName(this.calendar.activeDate);
    }
    const activeYear = this._dateAdapter.getYear(this.calendar.activeDate);
    const firstYearInView = this._dateAdapter.getYearName(
      this._dateAdapter.createDate(activeYear - (activeYear % 24), 0, 1)
    );
    const lastYearInView = this._dateAdapter.getYearName(
      this._dateAdapter.createDate(
        activeYear + yearsPerPage - 1 - (activeYear % 24),
        0,
        1
      )
    );
    return `${firstYearInView} \u2013 ${lastYearInView}`;
  }

  get periodButtonLabel(): string {
    return this.calendar.currentView === 'month'
      ? this._intl.switchToMultiYearViewLabel
      : this._intl.switchToMonthViewLabel;
  }

  /** The label for the the previous button. */
  get prevButtonLabel(): string {
    return {
      month: this._intl.prevMonthLabel,
      year: this._intl.prevYearLabel,
      'multi-year': this._intl.prevMultiYearLabel,
    }[this.calendar.currentView];
  }

  /** The label for the the next button. */
  get nextButtonLabel(): string {
    return {
      month: this._intl.nextMonthLabel,
      year: this._intl.nextYearLabel,
      'multi-year': this._intl.nextMultiYearLabel,
    }[this.calendar.currentView];
  }

  /** Handles user clicks on the period label. */
  currentPeriodClicked(): void {
    this.calendar.currentView =
      this.calendar.currentView === 'month' ? 'multi-year' : 'month';
  }

  /** Handles user clicks on the previous button. */
  previousClicked(): void {
    this.calendar.activeDate =
      this.calendar.currentView === 'month'
        ? this._dateAdapter.addCalendarMonths(this.calendar.activeDate, -1)
        : this._dateAdapter.addCalendarYears(
            this.calendar.activeDate,
            this.calendar.currentView === 'year' ? -1 : -yearsPerPage
          );
  }

  /** Handles user clicks on the next button. */
  nextClicked(): void {
    this.calendar.activeDate =
      this.calendar.currentView === 'month'
        ? this._dateAdapter.addCalendarMonths(this.calendar.activeDate, 1)
        : this._dateAdapter.addCalendarYears(
            this.calendar.activeDate,
            this.calendar.currentView === 'year' ? 1 : yearsPerPage
          );
  }

  /** Whether the previous period button is enabled. */
  previousEnabled(): boolean {
    if (!this.calendar.minDate) {
      return true;
    }
    return (
      !this.calendar.minDate ||
      !this._isSameView(this.calendar.activeDate, this.calendar.minDate)
    );
  }

  /** Whether the next period button is enabled. */
  nextEnabled(): boolean {
    return (
      !this.calendar.maxDate ||
      !this._isSameView(this.calendar.activeDate, this.calendar.maxDate)
    );
  }

  /** Whether the two dates represent the same view in the current view mode (month or year). */
  private _isSameView(date1: D, date2: D): boolean {
    if (this.calendar.currentView === 'month') {
      return (
        this._dateAdapter.getYear(date1) === this._dateAdapter.getYear(date2) &&
        this._dateAdapter.getMonth(date1) === this._dateAdapter.getMonth(date2)
      );
    }
    if (this.calendar.currentView === 'year') {
      return (
        this._dateAdapter.getYear(date1) === this._dateAdapter.getYear(date2)
      );
    }
    // Otherwise we are in 'multi-year' view.
    return (
      Math.floor(this._dateAdapter.getYear(date1) / yearsPerPage) ===
      Math.floor(this._dateAdapter.getYear(date2) / yearsPerPage)
    );
  }
}

import { FocusMonitor, _IdGenerator } from '@angular/cdk/a11y';
import { BACKSPACE, DELETE } from '@angular/cdk/keycodes';
import {
  AfterContentInit,
  AfterViewInit,
  ChangeDetectorRef,
  Component,
  ContentChild,
  ContentChildren,
  DoCheck,
  ElementRef,
  EventEmitter,
  Injector,
  Input,
  NgZone,
  OnDestroy,
  OnInit,
  Output,
  QueryList,
  ViewChild,
  ViewEncapsulation,
  booleanAttribute,
  inject,
  DOCUMENT,
} from '@angular/core';
import { Subject, Subscription, merge } from 'rxjs';
import { OuiChipAction, OuiChipContent } from './chip-action';
import {
  OuiChipAvatar,
  OuiChipEdit,
  OuiChipRemove,
  OuiChipTrailingIcon,
} from './chip-icons';
import {
  OUI_CHIP,
  OUI_CHIP_AVATAR,
  OUI_CHIP_EDIT,
  OUI_CHIP_REMOVE,
  OUI_CHIP_TRAILING_ICON,
} from './tokens';

/** Represents an event fired on an individual `oui-chip`. */
export interface OuiChipEvent {
  /** The chip the event was fired on. */
  chip: OuiChip;
}

/**
 * Once UI styled Chip base component. Used inside the OuiChipSet component.
 *
 * Extended by OuiChipOption and OuiChipRow for different interaction patterns.
 */
@Component({
  selector: 'oui-basic-chip, [oui-basic-chip], oui-chip, [oui-chip]',
  exportAs: 'ouiChip',
  templateUrl: 'chip.html',
  styleUrls: ['chip.scss'],
  host: {
    class: 'oui-chip',
    '[class]': '"oui-" + (color || "primary")',
    '[class.oui-chip--basic]': '_isBasicChip',
    '[class.oui-chip--standard]': '!_isBasicChip',
    '[class.oui-chip--disabled]': 'disabled',
    '[class.oui-chip-with-trailing-icon]': '_hasTrailingIcon()',
    '[class.oui-chip-with-avatar]': 'leadingIcon',
    '[class.oui-chip-highlighted]': 'highlighted',
    '[id]': 'id',
    '[attr.role]': 'role',
    '[attr.aria-label]': 'ariaLabel',
    '(keydown)': '_handleKeydown($event)',
  },
  encapsulation: ViewEncapsulation.None,
  providers: [{ provide: OUI_CHIP, useExisting: OuiChip }],
  imports: [OuiChipContent],
})
export class OuiChip
  implements OnInit, AfterViewInit, AfterContentInit, DoCheck, OnDestroy
{
  _changeDetectorRef = inject(ChangeDetectorRef);
  _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  protected _ngZone = inject(NgZone);
  private _focusMonitor = inject(FocusMonitor);

  protected _document = inject(DOCUMENT);

  /** Emits when the chip is focused. */
  readonly _onFocus = new Subject<OuiChipEvent>();

  /** Emits when the chip is blurred. */
  readonly _onBlur = new Subject<OuiChipEvent>();

  /** Whether this chip is a basic (unstyled) chip. */
  _isBasicChip = false;

  /** Role for the root of the chip. */
  @Input() role: string | null = null;

  /** Whether the chip has focus. */
  private _hasFocusInternal = false;

  /** Whether moving focus into the chip is pending. */
  private _pendingFocus: boolean = false;

  /** Subscription to changes in the chip's actions. */
  private _actionChanges: Subscription | undefined;

  /** All avatars present in the chip. */
  @ContentChildren(OUI_CHIP_AVATAR, { descendants: true })
  protected _allLeadingIcons!: QueryList<OuiChipAvatar>;

  /** All trailing icons present in the chip. */
  @ContentChildren(OUI_CHIP_TRAILING_ICON, { descendants: true })
  protected _allTrailingIcons!: QueryList<OuiChipTrailingIcon>;

  /** All edit icons present in the chip. */
  @ContentChildren(OUI_CHIP_EDIT, { descendants: true })
  protected _allEditIcons!: QueryList<OuiChipEdit>;

  /** All remove icons present in the chip. */
  @ContentChildren(OUI_CHIP_REMOVE, { descendants: true })
  protected _allRemoveIcons!: QueryList<OuiChipRemove>;

  _hasFocus() {
    return this._hasFocusInternal;
  }

  /** A unique id for the chip. If none is supplied, it will be auto-generated. */
  @Input() id: string = inject(_IdGenerator).getId('oui-chip-');

  /** ARIA label for the content of the chip. */
  @Input('aria-label') ariaLabel: string | null = null;

  /** ARIA description for the content of the chip. */
  @Input('aria-description') ariaDescription: string | null = null;

  /** Whether the chip list is disabled. */
  _chipListDisabled: boolean = false;

  /** Whether the chip was focused when it was removed. */
  _hadFocusOnRemove = false;

  private _textElement!: HTMLElement;

  /**
   * The value of the chip. Defaults to the content inside
   * the `oui-chip-action-label` element.
   */
  @Input()
  get value(): any {
    return this._value !== undefined
      ? this._value
      : this._textElement?.textContent?.trim();
  }
  set value(value: any) {
    this._value = value;
  }
  protected _value: any;

  /**
   * Color theme of the chip. Accepts primary, accent or warn.
   */
  @Input() color?: string | null;

  /**
   * Determines whether or not the chip displays the remove styling and emits (removed) events.
   */
  @Input({ transform: booleanAttribute })
  removable: boolean = true;

  /**
   * Colors the chip for emphasis as if it were selected.
   */
  @Input({ transform: booleanAttribute })
  highlighted: boolean = false;

  /** Whether the ripple effect is disabled or not. */
  @Input({ transform: booleanAttribute })
  disableRipple: boolean = false;

  /** Whether the chip is disabled. */
  @Input({ transform: booleanAttribute })
  get disabled(): boolean {
    return this._disabled || this._chipListDisabled;
  }
  set disabled(value: boolean) {
    this._disabled = value;
  }
  private _disabled = false;

  /** Emitted when a chip is to be removed. */
  @Output() readonly removed: EventEmitter<OuiChipEvent> =
    new EventEmitter<OuiChipEvent>();

  /** Emitted when the chip is destroyed. */
  @Output() readonly destroyed: EventEmitter<OuiChipEvent> =
    new EventEmitter<OuiChipEvent>();

  /** The unstyled chip selector for this component. */
  protected basicChipAttrName = 'oui-basic-chip';

  /** The chip's leading icon. */
  @ContentChild(OUI_CHIP_AVATAR) leadingIcon!: OuiChipAvatar;

  /** The chip's leading edit icon. */
  @ContentChild(OUI_CHIP_EDIT) editIcon!: OuiChipEdit;

  /** The chip's trailing icon. */
  @ContentChild(OUI_CHIP_TRAILING_ICON) trailingIcon!: OuiChipTrailingIcon;

  /** The chip's trailing remove icon. */
  @ContentChild(OUI_CHIP_REMOVE) removeIcon!: OuiChipRemove;

  /** Action receiving the primary set of user interactions. */
  @ViewChild(OuiChipAction) primaryAction!: OuiChipAction;

  protected _injector = inject(Injector);

  constructor() {
    this._monitorFocus();
  }

  ngOnInit() {
    const tagName = this._elementRef.nativeElement.tagName.toLowerCase();
    this._isBasicChip =
      this._elementRef.nativeElement.hasAttribute(this.basicChipAttrName) ||
      tagName === this.basicChipAttrName;
  }

  ngAfterViewInit() {
    this._textElement = this._elementRef.nativeElement.querySelector(
      '.oui-chip-action-label'
    )!;

    if (this._pendingFocus) {
      this._pendingFocus = false;
      this.focus();
    }
  }

  ngAfterContentInit(): void {
    this._actionChanges = merge(
      this._allLeadingIcons.changes,
      this._allTrailingIcons.changes,
      this._allRemoveIcons.changes
    ).subscribe(() => this._changeDetectorRef.markForCheck());
  }

  // eslint-disable-next-line @angular-eslint/no-empty-lifecycle-method
  ngDoCheck(): void {
    // Reserved for subclasses. Kept as part of the MatChip-compatible API.
  }

  ngOnDestroy() {
    this.destroyed.emit({ chip: this });
    this.destroyed.complete();
    this._focusMonitor.stopMonitoring(this._elementRef);
    this._actionChanges?.unsubscribe();
  }

  /**
   * Allows for programmatic removal of the chip.
   *
   * Informs any listeners of the removal request. Does not remove the chip from the DOM.
   */
  remove(): void {
    if (this.removable) {
      this._hadFocusOnRemove = this._hasFocus();
      this.removed.emit({ chip: this });
    }
  }

  /** Whether or not the ripple should be disabled. */
  _isRippleDisabled(): boolean {
    return (
      this.disabled ||
      this.disableRipple ||
      this._isBasicChip ||
      !this._hasInteractiveActions()
    );
  }

  /** Returns whether the chip has a trailing icon. */
  _hasTrailingIcon() {
    return !!(this.trailingIcon || this.removeIcon);
  }

  /** Returns whether the chip has a leading action icon. */
  _hasLeadingActionIcon() {
    return !!this.editIcon;
  }

  /** Returns whether the chip has a leading graphic. */
  _hasLeadingGraphic() {
    return !!this.leadingIcon;
  }

  /** Handles keyboard events on the chip. */
  _handleKeydown(event: KeyboardEvent) {
    if (
      (event.keyCode === BACKSPACE && !event.repeat) ||
      event.keyCode === DELETE
    ) {
      event.preventDefault();
      this.remove();
    }
  }

  /** Allows for programmatic focusing of the chip. */
  focus(): void {
    if (!this.disabled) {
      if (this.primaryAction) {
        this.primaryAction.focus();
      } else {
        this._pendingFocus = true;
      }
    }
  }

  /** Gets the action that contains a specific target node. */
  _getSourceAction(target: Node): OuiChipAction | undefined {
    return this._getActions().find((action) => {
      const element = action._elementRef.nativeElement;
      return element === target || element.contains(target);
    });
  }

  /** Gets all of the actions within the chip. */
  _getActions(): OuiChipAction[] {
    const result: OuiChipAction[] = [];

    if (this.primaryAction) {
      result.push(this.primaryAction);
    }

    if (this.editIcon) {
      result.push(this.editIcon);
    }

    if (this.removeIcon) {
      result.push(this.removeIcon);
    }

    return result;
  }

  /** Handles interactions with the primary action of the chip. */
  _handlePrimaryActionInteraction() {
    // Empty here, but is overwritten in child classes.
  }

  /** Returns whether the chip has any interactive actions. */
  _hasInteractiveActions(): boolean {
    return this._getActions().length > 0;
  }

  /** Handles interactions with the edit action of the chip. */
  _edit(_event: Event) {
    // Empty here, but is overwritten in child classes.
  }

  /** Starts the focus monitoring process on the chip. */
  private _monitorFocus() {
    this._focusMonitor.monitor(this._elementRef, true).subscribe((origin) => {
      const hasFocus = origin !== null;

      if (hasFocus !== this._hasFocusInternal) {
        this._hasFocusInternal = hasFocus;

        if (hasFocus) {
          this._onFocus.next({ chip: this });
        } else {
          this._changeDetectorRef.markForCheck();
          setTimeout(() =>
            this._ngZone.run(() => this._onBlur.next({ chip: this }))
          );
        }
      }
    });
  }
}

