import {
  ChangeDetectorRef,
  Component,
  computed,
  effect,
  inject,
  input,
  output,
  signal,
} from '@angular/core';
import { DomSanitizer } from '@angular/platform-browser';
import { UntypedFormControl } from '@angular/forms';
import { COMMA, ENTER } from '@angular/cdk/keycodes';
import {
  ChipsAutocompleteSelectedEvent,
  OuiChipInputEvent,
  OuiIconRegistry,
} from '../../components';
import { FRUITS, INITIAL_FRUITS } from './const';

@Component({
  selector: 'oui-chips-autocomplete-storybook',
  template: `
    <oui-form-field
      [appearance]="appearance()"
      style="max-width: 400px; display: block;"
    >
      <oui-chip-grid
        #chipGrid
        [disabled]="disabled()"
        [value]="fruits()"
        (change)="onChange($event)"
      >
        @for (fruit of fruits(); track fruit) {
        <oui-chip-row [value]="fruit" (removed)="remove(fruit)">
          {{ fruit }}
          <button ouiChipRemove aria-label="Remove {{ fruit }}">
            <oui-icon svgIcon="x-close-small"></oui-icon>
          </button>
        </oui-chip-row>
        }
      </oui-chip-grid>
      <input
        placeholder="New fruit..."
        [ouiChipAutocomplete]="auto"
        [formControl]="currentFruitCtrl"
        [ouiChipInputFor]="chipGrid"
        [ouiChipInputSeparatorKeyCodes]="separatorKeysCodes"
        [ouiChipInputAddOnBlur]="addOnBlur()"
        (ouiChipInputTokenEnd)="add($event)"
      />
      <oui-chips-autocomplete
        #auto="ouiChipsAutocomplete"
        (optionSelected)="selected($event)"
      >
        @for (fruit of filteredFruits(); track fruit) {
        <oui-chips-option [value]="fruit">{{ fruit }}</oui-chips-option>
        }
      </oui-chips-autocomplete>
    </oui-form-field>
  `,
  standalone: false,
})
export class OuiChipsAutocompleteStorybook {
  readonly separatorKeysCodes: number[] = [ENTER, COMMA];
  readonly currentFruitCtrl = new UntypedFormControl('');
  private _cdr = inject(ChangeDetectorRef);

  readonly currentFruit = signal('');
  readonly fruits = signal<string[]>([...INITIAL_FRUITS]);

  readonly filteredFruits = computed(() => {
    const currentFruit = this.currentFruit().toLowerCase();
    return currentFruit
      ? FRUITS.filter((fruit) => fruit.toLowerCase().includes(currentFruit))
      : FRUITS.slice();
  });

  readonly appearance = input<string>('standard');
  readonly disabled = input<boolean>(false);
  readonly addOnBlur = input<boolean>(true);

  readonly chipAdded = output<string>();
  readonly chipRemoved = output<string>();
  readonly autocompleteOptionSelected = output<string>();

  constructor() {
    const ouiIconRegistry = inject(OuiIconRegistry);
    const domSanitizer = inject(DomSanitizer);

    ouiIconRegistry.addSvgIconSet(
      domSanitizer.bypassSecurityTrustResourceUrl(
        'https://cdn.icomoon.io/135790/oncehub-20/symbol-defs.svg?v7tuaj'
      )
    );

    this.currentFruitCtrl.valueChanges.subscribe((value: string) => {
      this.currentFruit.set(value ?? '');
    });

    effect(() => {
      this.fruits();
      this._cdr.markForCheck();
    });
  }

  add(event: OuiChipInputEvent): void {
    const value = (event.value || '').trim();

    if (value && !this.fruits().includes(value)) {
      this.fruits.update((fruits) => [...fruits, value]);
      this.chipAdded.emit(value);
    }

    event.chipInput.clear();
    this.currentFruitCtrl.setValue('');
  }

  remove(fruit: string): void {
    this.fruits.update((fruits) => {
      const index = fruits.indexOf(fruit);
      if (index < 0) {
        return fruits;
      }
      const next = [...fruits];
      next.splice(index, 1);
      return next;
    });
    this.chipRemoved.emit(fruit);
  }

  selected(event: ChipsAutocompleteSelectedEvent): void {
    const value = event.option.viewValue;
    if (value && !this.fruits().includes(value)) {
      this.fruits.update((fruits) => [...fruits, value]);
      this.autocompleteOptionSelected.emit(value);
    }
    this.currentFruitCtrl.setValue('');
    event.option.deselect();
  }

  onChange(_event: any): void {}
}

import { FocusKeyManager } from '@angular/cdk/a11y';
import { Directionality } from '@angular/cdk/bidi';
import {
  AfterViewInit,
  ChangeDetectorRef,
  Component,
  ContentChildren,
  ElementRef,
  Input,
  OnDestroy,
  QueryList,
  ViewEncapsulation,
  booleanAttribute,
  numberAttribute,
  inject,
} from '@angular/core';
import { Observable, Subject, merge } from 'rxjs';
import { startWith, switchMap, takeUntil } from 'rxjs/operators';
import { OuiChip, OuiChipEvent } from './chip';
import { OuiChipAction, OuiChipContent } from './chip-action';

/**
 * Basic container component for the OuiChip component.
 *
 * Extended by OuiChipListbox and OuiChipGrid for different interaction patterns.
 */
@Component({
  selector: 'oui-chip-set',
  template: `
    <div class="oui-chip-set__chips" role="presentation">
      <ng-content></ng-content>
    </div>
  `,
  styleUrls: ['chip-set.scss'],
  host: {
    class: 'oui-chip-set',
    '(keydown)': '_handleKeydown($event)',
    '[attr.role]': 'role',
  },
  encapsulation: ViewEncapsulation.None,
})
export class OuiChipSet implements AfterViewInit, OnDestroy {
  protected _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  protected _changeDetectorRef = inject(ChangeDetectorRef);
  private _dir = inject(Directionality, { optional: true });

  /** Index of the last destroyed chip that had focus. */
  protected _lastDestroyedFocusedChipIndex: number | null = null;

  /** Used to manage focus within the chip list. */
  protected _keyManager!: FocusKeyManager<OuiChipAction>;

  /** Subject that emits when the component has been destroyed. */
  protected _destroyed = new Subject<void>();

  /** Role to use if it hasn't been overwritten by the user. */
  protected _defaultRole = 'presentation';

  /** Combined stream of all of the child chips' focus events. */
  get chipFocusChanges(): Observable<OuiChipEvent> {
    return this._getChipStream((chip) => chip._onFocus);
  }

  /** Combined stream of all of the child chips' destroy events. */
  get chipDestroyedChanges(): Observable<OuiChipEvent> {
    return this._getChipStream((chip) => chip.destroyed);
  }

  /** Combined stream of all of the child chips' remove events. */
  get chipRemovedChanges(): Observable<OuiChipEvent> {
    return this._getChipStream((chip) => chip.removed);
  }

  /** Whether the chip set is disabled. */
  @Input({ transform: booleanAttribute })
  get disabled(): boolean {
    return this._disabled;
  }
  set disabled(value: boolean) {
    this._disabled = value;
    this._syncChipsState();
  }
  protected _disabled: boolean = false;

  /** Whether the chip list contains chips or not. */
  get empty(): boolean {
    return !this._chips || this._chips.length === 0;
  }

  /** The ARIA role applied to the chip set. */
  @Input()
  get role(): string | null {
    if (this._explicitRole) {
      return this._explicitRole;
    }

    return this.empty ? null : this._defaultRole;
  }

  /** Tabindex of the chip set. */
  @Input({
    transform: (value: unknown) => (value == null ? 0 : numberAttribute(value)),
  })
  tabIndex: number = 0;

  set role(value: string | null) {
    this._explicitRole = value;
  }
  private _explicitRole: string | null = null;

  /** Whether any of the chips inside of this chip-set has focus. */
  get focused(): boolean {
    return this._hasFocusedChip();
  }

  /** The chips that are part of this chip set. */
  @ContentChildren(OuiChip, {
    descendants: true,
  })
  _chips!: QueryList<OuiChip>;

  /** Flat list of all the actions contained within the chips. */
  _chipActions = new QueryList<OuiChipAction>();

  ngAfterViewInit() {
    this._setUpFocusManagement();
    this._trackChipSetChanges();
    this._trackDestroyedFocusedChip();
  }

  ngOnDestroy() {
    this._keyManager?.destroy();
    this._chipActions.destroy();
    this._destroyed.next();
    this._destroyed.complete();
  }

  /** Checks whether any of the chips is focused. */
  protected _hasFocusedChip() {
    return this._chips && this._chips.some((chip) => chip._hasFocus());
  }

  /** Syncs the chip-set's state with the individual chips. */
  protected _syncChipsState() {
    this._chips?.forEach((chip) => {
      chip._chipListDisabled = this._disabled;
      chip._changeDetectorRef.markForCheck();
    });
  }

  /** Dummy method for subclasses to override. Base chip set cannot be focused. */
  focus() {}

  /** Handles keyboard events on the chip set. */
  _handleKeydown(event: KeyboardEvent) {
    if (this._originatesFromChip(event)) {
      this._keyManager.onKeydown(event);
    }
  }

  /**
   * Utility to ensure all indexes are valid.
   *
   * @param index The index to be checked.
   * @returns True if the index is valid for our list of chips.
   */
  protected _isValidIndex(index: number): boolean {
    return index >= 0 && index < this._chips.length;
  }

  /**
   * Removes the `tabindex` from the chip set and resets it back afterwards, allowing the
   * user to tab out of it. This prevents the set from capturing focus and redirecting
   * it back to the first chip, creating a focus trap, if it user tries to tab away.
   */
  protected _allowFocusEscape() {
    const previous = this._elementRef.nativeElement.tabIndex;

    if (previous !== -1) {
      this._elementRef.nativeElement.tabIndex = -1;

      setTimeout(() => (this._elementRef.nativeElement.tabIndex = previous));
    }
  }

  /**
   * Gets a stream of events from all the chips within the set.
   * The stream will automatically incorporate any newly-added chips.
   */
  protected _getChipStream<T, C extends OuiChip = OuiChip>(
    mappingFunction: (chip: C) => Observable<T>
  ): Observable<T> {
    return this._chips.changes.pipe(
      startWith(null),
      switchMap(() =>
        merge(...(this._chips as QueryList<C>).map(mappingFunction))
      )
    );
  }

  /** Checks whether an event comes from inside a chip element. */
  protected _originatesFromChip(event: Event): boolean {
    let currentElement = event.target as HTMLElement | null;

    while (
      currentElement &&
      currentElement !== this._elementRef.nativeElement
    ) {
      if (currentElement.classList.contains('oui-chip')) {
        return true;
      }
      currentElement = currentElement.parentElement;
    }
    return false;
  }

  /** Sets up the chip set's focus management logic. */
  private _setUpFocusManagement() {
    this._chips.changes
      .pipe(startWith(this._chips))
      .subscribe((chips: QueryList<OuiChip>) => {
        const actions: OuiChipAction[] = [];
        chips.forEach((chip) =>
          chip._getActions().forEach((action) => actions.push(action))
        );
        this._chipActions.reset(actions);
        this._chipActions.notifyOnChanges();
      });

    this._keyManager = new FocusKeyManager(this._chipActions)
      .withVerticalOrientation()
      .withHorizontalOrientation(this._dir ? this._dir.value : 'ltr')
      .withHomeAndEnd()
      .skipPredicate((action) => this._skipPredicate(action));

    this.chipFocusChanges
      .pipe(takeUntil(this._destroyed))
      .subscribe(({ chip }) => {
        const action = chip._getSourceAction(document.activeElement as Element);

        if (action) {
          this._keyManager.updateActiveItem(action);
        }
      });

    this._dir?.change
      .pipe(takeUntil(this._destroyed))
      .subscribe((direction) =>
        this._keyManager.withHorizontalOrientation(direction)
      );
  }

  /**
   * Determines if key manager should avoid putting a given chip action in the tab index. Skip
   * non-interactive and disabled actions since the user can't do anything with them.
   */
  protected _skipPredicate(action: OuiChipContent): boolean {
    return action.disabled;
  }

  /** Listens to changes in the chip set and syncs up the state of the individual chips. */
  private _trackChipSetChanges() {
    this._chips.changes
      .pipe(startWith(null), takeUntil(this._destroyed))
      .subscribe(() => {
        if (this.disabled) {
          Promise.resolve().then(() => this._syncChipsState());
        }

        this._redirectDestroyedChipFocus();
      });
  }

  /** Starts tracking the destroyed chips in order to capture the focused one. */
  private _trackDestroyedFocusedChip() {
    this.chipDestroyedChanges
      .pipe(takeUntil(this._destroyed))
      .subscribe((event: OuiChipEvent) => {
        const chipArray = this._chips.toArray();
        const chipIndex = chipArray.indexOf(event.chip);
        const hasFocus = event.chip._hasFocus();
        const wasLastFocused =
          event.chip._hadFocusOnRemove &&
          this._keyManager.activeItem &&
          event.chip._getActions().includes(this._keyManager.activeItem);

        const shouldMoveFocus = hasFocus || wasLastFocused;

        if (this._isValidIndex(chipIndex) && shouldMoveFocus) {
          this._lastDestroyedFocusedChipIndex = chipIndex;
        }
      });
  }

  /**
   * Finds the next appropriate chip to move focus to,
   * if the currently-focused chip is destroyed.
   */
  protected _redirectDestroyedChipFocus() {
    if (this._lastDestroyedFocusedChipIndex == null) {
      return;
    }

    if (this._chips.length) {
      const newIndex = Math.min(
        this._lastDestroyedFocusedChipIndex,
        this._chips.length - 1
      );
      const chipToFocus = this._chips.toArray()[newIndex];

      if (chipToFocus.disabled) {
        if (this._chips.length === 1) {
          this.focus();
        } else {
          this._keyManager.setPreviousItemActive();
        }
      } else {
        chipToFocus.focus();
      }
    } else {
      this.focus();
    }

    this._lastDestroyedFocusedChipIndex = null;
  }
}

styleUrlsData.data:
.oui-chip-set {
  display: flex;
  width: 100%;

  &:focus {
    outline: none;
  }

  .oui-chip-set__chips {
    display: flex;
    flex-flow: row wrap;
    align-items: center;
    min-width: 100%;
    margin-left: -8px;
    margin-right: 0;
  }

  .oui-chip {
    margin: 4px 0 4px 8px;
  }

  [dir='rtl'] & {
    .oui-chip-set__chips {
      margin-left: 0;
      margin-right: -8px;
    }

    .oui-chip {
      margin-left: 0;
      margin-right: 8px;
    }
  }
}

.oui-chip-set-stacked {
  flex-direction: column;
  align-items: flex-start;

  .oui-chip {
    width: 100%;
  }
}

input.oui-chip-input {
  flex: 1 0 150px;
  margin: 4px 0 4px 8px;
  height: 32px;
  border: none;
  outline: none;
  background: transparent;
  font-family: inherit;
  font-size: 14px;
  color: inherit;
  padding: 0;

  &:focus {
    outline: none;
  }

  &::placeholder {
    color: #666;
    opacity: 1;
  }
}

/* When the input lives as a sibling of the chip-set inside form-field-infix
   (the structure Angular Material documents for chips-autocomplete), drop
   the horizontal margin so the input sits flush on its own line below the
   chips. Mirrors Material's `.mat-mdc-chip-set + input.mat-mdc-chip-input`
   rule. */
oui-chip-set + input.oui-chip-input,
oui-chip-grid + input.oui-chip-input {
  margin-left: 0;
  margin-right: 0;
  display: block;
  width: 100%;
  flex: 0 0 auto;
}

/* Chips autocomplete: background and bottom border for the chips + input wrapper */
.oui-form-field-type-oui-chip-grid {
  .oui-form-field-flex {
    padding: 0 14px;
    background: #f6f6f6;
    border-bottom: 1px solid #c8c8c8;
    transition: border-color 0.5s;
  }

  &.oui-focused .oui-form-field-flex {
    border-bottom-color: #00a4ff;
  }
}

