  close = this.closed;

  constructor() {}

  ngOnInit() {
    this.setPositionClasses();
  }

  ngAfterContentInit() {
    this._keyManager = new FocusKeyManager<OuiMenuItem>(this._items)
      .withWrap()
      .withTypeAhead();
    this._tabSubscription = this._keyManager.tabOut.subscribe(() =>
      this.closed.emit('tab')
