    return (
      searchField &&
      searchField.tagName &&
      searchField.tagName.toLowerCase() === 'input'
    );
  }
  /** Handles keyboard events when the selected is open. */
  private _handleOpenKeydown(event: KeyboardEvent): void {
    const keyCode = event.keyCode;
    const isArrowKey = keyCode === DOWN_ARROW || keyCode === UP_ARROW;
    const manager = this._keyManager;
    const normalNavigationCheck =
      (keyCode !== TAB || !this.multiple) &&
      !(keyCode === ENTER || keyCode === SPACE);
    // Handles TAB press when panel is open to focus the cancel || done button
    this.tabbedKeyMethod(event);
    // There is search field inside the list
    if (this.searchCheck()) {
      this.isSearchFieldPresent = true;
      if (keyCode === SPACE) {
        return;
      }
    }
    if (keyCode === HOME || keyCode === END) {
      event.preventDefault();
      this.homeOrEndPressed(keyCode, manager);
    } else if (isArrowKey && event.altKey) {
      // Close the select on ALT + arrow key to match the native <select>
      event.preventDefault();
      this.close();
    } else if (
      (keyCode === ENTER || keyCode === SPACE) &&
      manager.activeItem &&
      !hasModifierKey(event)
    ) {
      event.preventDefault();
      manager.activeItem._selectViaInteraction();
    } else if (this._multiple && keyCode === A && event.ctrlKey) {
      event.preventDefault();
      this.handleCtrlKey();
    } else if (normalNavigationCheck) {
      // Check for non multiple select dropdown that the key pressed is not Tab, Space, Enter
      if (!this.isSearchFieldPresent) this.focus();
      this.handleScrolling(manager, event, isArrowKey, keyCode);
    }
  }

  /**
   * Handle ctrl key
   */
  private handleCtrlKey() {
    const hasDeselectedOptions = this.options.some(
      (opt) => !opt.disabled && !opt.selected
    );

    this.options.forEach((option) => {
      if (!option.disabled) {
        if (hasDeselectedOptions) {
          option.select();
        } else {
          option.deselect();
        }
      }
    });
  }

  /**
   * @param manager
   * @param event
   * @param isArrowKey
   * @param keyCode
   */
  private handleScrolling(
    manager: ActiveDescendantKeyManager<OuiOption>,
    event: KeyboardEvent,
    isArrowKey: boolean,
    keyCode: number
  ) {
    const previouslyFocusedIndex = manager.activeItemIndex;

    manager.onKeydown(event);

    if (
      this._multiple &&
      isArrowKey &&
      event.shiftKey &&
      manager.activeItem &&
      manager.activeItemIndex !== previouslyFocusedIndex
    ) {
      manager.activeItem._selectViaInteraction();
    }
    if (isArrowKey && manager.activeItemIndex !== previouslyFocusedIndex) {
      this._scrollToOption();
    } else {
      // First or last
      if (keyCode === DOWN_ARROW) {
        manager.setFirstItemActive();
        this._setScrollTop(0);
      }
      if (keyCode === UP_ARROW) {
        manager.setLastItemActive();
        this._scrollToOption();
      }
    }
  }

  _onFocus() {
    if (!this.disabled) {
      this._focused = true;
      this.stateChanges.next();
    }
  }

  /**
   * Calls the touched callback only if the panel is closed. Otherwise, the trigger will
   * "blur" to the panel when it opens, causing a false positive.
   */
  _onBlur() {
    this._focused = false;
    // this.isSearchFieldPresent = false;

    if (!this.disabled && !this.panelOpen) {
      this._onTouched();
      this._changeDetectorRef.markForCheck();
      this.stateChanges.next();
    }
  }

  /**
   * Callback that is invoked when the overlay panel has been attached.
   */
  _onAttached(): void {
    this.overlayDir.positionChange.pipe(take(1)).subscribe(() => {
      this._setPseudoCheckboxPaddingSize();
      this._changeDetectorRef.detectChanges();
      this.panel.nativeElement.scrollTop = this._scrollTop;
    });
  }

  /** Returns the theme to be used on the panel. */
  _getPanelTheme(): string {
    return this._parentFormField ? `oui-${this._parentFormField.color}` : '';
  }

  // TODO(josephperrott): Remove after 2018 spec updates are fully merged.
  /** Sets the pseudo checkbox padding size based on the width of the pseudo checkbox. */
  private _setPseudoCheckboxPaddingSize() {
    if (!SELECT_MULTIPLE_PANEL_PADDING_X && this.multiple) {
      const pseudoCheckbox = this.panel.nativeElement.querySelector(
        '.oui-pseudo-checkbox'
      );
      if (pseudoCheckbox) {
        SELECT_MULTIPLE_PANEL_PADDING_X =
          SELECT_PANEL_PADDING_X * 1.5 + <number>pseudoCheckbox.offsetWidth;
      }
    }
  }

  /** Whether the select has a value. */
  get empty(): boolean {
    return !this._selectionModel || this._selectionModel.isEmpty();
  }

  private _initializeSelection(): void {
    // Defer setting the value in order to avoid the "Expression
    // has changed after it was checked" errors from Angular.
    Promise.resolve().then(() => {
      this._setSelectionByValue(
        this.ngControl ? this.ngControl.value : this._value
      );
      if (this.multiple) {
        this._highlightFirstFilteredOption();
      }
    });
  }

  /**
   * Sets the selected option based on a value. If no option can be
   * found with the designated value, the select trigger is cleared.
   */
  private _setSelectionByValue(value: any): void {
    if (this.multiple && value) {
      if (!Array.isArray(value)) {
        throw getOuiSelectNonArrayValueError();
      }

      this._selectionModel.clear();
      value.forEach((currentValue: any) => this._selectValue(currentValue));
      this._sortValues();
    } else {
      this._selectionModel.clear();
      const correspondingOption = this._selectValue(value);
      // Shift focus to the active item. Note that we shouldn't do this in multiple
      // mode, because we don't know what option the user interacted with last.
      if (correspondingOption) {
        this._keyManager.setActiveItem(correspondingOption);
      }
    }
    this._changeDetectorRef.markForCheck();
  }

  /**
   * Finds and selects and option based on its value.
   *
   * @returns Option that has the corresponding value.
   */
  private _selectValue(value: any): OuiOption | undefined {
    const correspondingOption = this.options.find((option: OuiOption) => {
      try {
        // Treat null as a special reset value.
        return option.value != null && this._compareWith(option.value, value);
      } catch (error) {
        if (isDevMode()) {
          // Notify developers of errors in their comparator.
          console.warn(error);
        }
        return false;
      }
    });

    if (correspondingOption) {
      this._selectionModel.select(correspondingOption);
    }

    return correspondingOption;
  }

  /** Sets up a key manager to listen to keyboard events on the overlay panel. */
  private _initKeyManager() {
    this._keyManager = new ActiveDescendantKeyManager<OuiOption>(this.options)
      .withTypeAhead()
      .withVerticalOrientation()
      .withHorizontalOrientation(this._isRtl() ? 'rtl' : 'ltr')
      .withAllowedModifierKeys(['shiftKey']);

    this._keyManager.tabOut.pipe(takeUntil(this._destroy)).subscribe(() => {
      // Restore focus to the trigger before closing. Ensures that the focus
      // position won't be lost if the user got focus into the overlay.
      if (!this.singleActionItem) {
        this.focus();
        this.close();
      }
    });

    this._keyManager.change.pipe(takeUntil(this._destroy)).subscribe(() => {
      if (this._panelOpen && this.panel) {
        // Panel is opened
        // Need not to scroll
      } else if (
        !this._panelOpen &&
        !this.multiple &&
        this._keyManager.activeItem
      ) {
        this._keyManager.activeItem._selectViaInteraction();
      }
    });
  }

  /** Drops current option subscriptions and IDs and resets from scratch. */
  private _resetOptions(): void {
    const changedOrDestroyed = merge(this.options.changes, this._destroy);
    this.optionSelectionChanges
      .pipe(takeUntil(changedOrDestroyed))
      .subscribe((event) => {
        this._onSelect(event.source, event.isUserInput);

        if (event.isUserInput && !this.multiple && this._panelOpen) {
          this.close();
          this.focus();
        }
      });

    // Listen to changes in the internal state of the options and react accordingly.
    // Handles cases like the labels of the selected options changing.
    merge(...this.options.map((option) => option._stateChanges))
      .pipe(takeUntil(changedOrDestroyed))
      .subscribe(() => {
        this._changeDetectorRef.markForCheck();
        this.stateChanges.next();
      });

    this._setOptionIds();
  }

  /** Invoked when an option is clicked. */
  private _onSelect(option: OuiOption, isUserInput: boolean): void {
    const wasSelected = this._selectionModel.isSelected(option);

    if (option.value == null && !this._multiple) {
      option.deselect();
      this._selectionModel.clear();
      this._propagateChanges(option.value);
    } else {
      if (option.selected) {
        this._selectionModel.select(option);
      } else {
        this._selectionModel.deselect(option);
      }

      if (isUserInput) {
        this._keyManager.setActiveItem(option);
      }

      if (this.multiple) {
        this._sortValues();

        if (isUserInput) {
          // In case the user selected the option with their mouse, we
          // want to restore focus back to the trigger, in order to
          // prevent the select keyboard controls from clashing with
          // the ones from `oui-option`.
          this.focus();
        }
      }
    }

    if (wasSelected !== this._selectionModel.isSelected(option)) {
      this._propagateChanges();
    }
    if (Array.isArray(this.selected) && this.selected.length <= 0) {
      this.disableDoneButton = true;
    }
    if (
      this.multiple &&
      isUserInput &&
      Array.isArray(this.selected) &&
      this.selected.length > 0
    ) {
      this.disableDoneButton = this._isDoneButtonDisabled();
    }
    this.stateChanges.next();
  }
  discardRecentChanges() {
    this.value = this.savedValues;
    this._setSelectionByValue(this.value);
    this.disableDoneButton = true;
    this.close();
  }
  doneRecentChanges() {
    this.savedValues = this.value;
    this.disableDoneButton = true;
    this.previouslySelected = [...this.setSelectedOptions];
    this.saveSelectionChange.emit(new OuiSelectChange(this, this.value));
    this.close();
  }

  handleSingleActionItemClick() {
    this.singleSelectionChange.emit();
    this.close();
  }

  /** Determine whether the "Done" button should be enabled or disabled based on the selection state */
  _isDoneButtonDisabled() {
    const selectedItems = (this.selected as OuiOption[]).map(
      (option) => option.value
    );
    if (this.allowNoSelection) {
      return false;
    }
    return selectedItems.length === 0;
  }

  /** Sorts the selected values in the selected based on their order in the panel. */
  private _sortValues() {
    if (this.multiple) {
      const options = this.options.toArray();

      this._selectionModel.sort((a, b) =>
        this.sortComparator
          ? this.sortComparator(a, b, options)
          : options.indexOf(a) - options.indexOf(b)
      );
      this.stateChanges.next();
    }
  }

  /** Emits change event to set the model value. */
  private _propagateChanges(fallbackValue?: any): void {
    let valueToEmit: any = null;

    if (this.multiple) {
      valueToEmit = (this.selected as OuiOption[]).map(
        (option) => option.value
      );
    } else {
      valueToEmit = this.selected
        ? (this.selected as OuiOption).value
        : fallbackValue;
    }

    this._value = valueToEmit;
    this.valueChange.emit(valueToEmit);
    this._onChange(valueToEmit);
    this.selectionChange.emit(new OuiSelectChange(this, valueToEmit));
    this._changeDetectorRef.markForCheck();
  }

  /** Records option IDs to pass to the aria-owns property. */
  private _setOptionIds() {
    this._optionIds = this.options.map((option) => option.id).join(' ');
  }

  /**
   * Highlights the selected item. If no option is selected, it will highlight
   * the first item instead.
   */
  private _highlightCorrectOption(): void {
    if (this.multiple) {
      this._highlightFirstFilteredOption();
    } else if (this._keyManager) {
      if (this.empty) {
        this._keyManager.setFirstItemActive();
      } else {
        this._keyManager.setActiveItem(this._selectionModel.selected[0]);
      }
    }
  }

  /**
   * Highlights the first of the filtered options if no element is currently highlighted
   */
  private _highlightFirstFilteredOption(): void {
    if (this._keyManager) {
      const activeElement = this._keyManager.activeItem?._getHostElement();
      // activeElement is not part of DOM if there is no parent element
      if (!activeElement || !activeElement.parentElement) {
        // highlight first element if there is no active element or active element is not part of DOM
        this._keyManager.setFirstItemActive();
      }
    }
  }

  /** Focuses the select element. */
  focus(): void {
    this._elementRef.nativeElement.focus();
  }

  /** Returns the aria-label of the select component. */
  _getAriaLabel(): string | null {
    // If an ariaLabelledby value has been set by the consumer, the select should not overwrite the
    // `aria-labelledby` value by setting the ariaLabel to the placeholder.
    return this.ariaLabelledby ? null : this.ariaLabel || this.placeholder;
  }

  /** Returns the aria-labelledby of the select component. */
  _getAriaLabelledby(): string | null {
    if (this.ariaLabelledby) {
      return this.ariaLabelledby;
    }

    return null;
  }

  /** Determines the `aria-activedescendant` to be set on the host. */
  _getAriaActiveDescendant(): string | null {
    if (this.panelOpen && this._keyManager && this._keyManager.activeItem) {
      return this._keyManager.activeItem.id;
    }

    return null;
  }

  /**
   * Implemented as part of OuiFormFieldControl.
   *
   * @docs-private
   */
  setDescribedByIds(ids: string[]) {
    this._ariaDescribedby = ids.join(' ');
  }

  /**
   * Implemented as part of OuiFormFieldControl.
   *
   * @docs-private
   */
  onContainerClick() {
    this.focus();
    this.open();
  }

  /**
   * Implemented as part of OuiFormFieldControl.
   *
   * @docs-private
   */
  get shouldLabelFloat(): boolean {
    return this._panelOpen || !this.empty;
  }

  /**
   * Add outer class to perfect scrollbar
   * This is added only when there is a search field
   */
  ouiSelectInputOuter() {
    this.ouiSelectInputOuterClassName = 'oui-select-input-outer';
  }

  /**
   * Custom overlay class for cdk overlay container
   */
  openCdk() {
    this.overlayDir.positionChange.pipe(take(1)).subscribe((e) => {
      this.cdkConnectionOverlayPanel = '';
      if (e.connectionPair.originY === 'top') {
        this.cdkConnectionOverlayPanel = 'select-overlay-top';
      }
      this._changeDetectorRef.detectChanges();
      setTimeout((_) => this._scrollToOption());
    });

    const cdkOverLayContainer = this._document.querySelector(
      '.cdk-overlay-container'
    );
    const ouiSelectPanel = this._document.querySelector(
      '.oui-select-panel'
    ) as HTMLElement;
    if (cdkOverLayContainer) {
      cdkOverLayContainer.classList.add('oui-select-overlay-container');
    }
    const containerWidth = this._elementRef.nativeElement.offsetWidth;
    if (ouiSelectPanel) {
      ouiSelectPanel.style.width = `${containerWidth}px`;
    }
    const searchQueryString = '.oui-select-search-inner';
    if (this._document.querySelector(searchQueryString)) {
      this.scrollCalc(searchQueryString);
    }
  }
  scrollCalc(selectQueryString: string) {
    const searchInput = this._document.querySelector(
      selectQueryString
    ) as HTMLElement;
    const outter = this._document.querySelector(
      '.oui-select-panel'
    ) as HTMLElement;
    let inner = this._document.querySelector('.oui-option') as HTMLElement;
    if (inner === null) {
      inner = { offsetWidth: 0 } as HTMLElement;
    }
    const scrollbarWidth = outter.offsetWidth - inner.offsetWidth;
    if (scrollbarWidth > 5) {
      searchInput.style.width = `${inner.offsetWidth}px`;
    } else {
      searchInput.style.width = '100%';
    }
  }

  /**
   * Given that we are not actually focusing active options, we must manually adjust scroll
   * to reveal options below the fold. First, we find the offset of the option from the top
   * of the panel. If that offset is below the fold, the new scrollTop will be the offset -
   * the panel height + the option height, so the active option will be just visible at the
   * bottom of the panel. If that offset is above the top of the visible panel, the new scrollTop
   * will become the offset. If that offset is visible within the panel already, the scrollTop is
   * not adjusted.
   */
  private _scrollToOption(): void {
    const manager = this._keyManager;
    const index = manager.activeItemIndex || 0;
    const labelCount = _countGroupLabelsBeforeOption(
      index,
      this.options,
      this.optionGroups
    );
    const selectedOption = manager.activeItem?._getHostElement();
    const selectActionWrapperElement = this._document.querySelector(
      '.oui-select-action-wrapper'
    ) as HTMLElement;
    const selectPanelElement = this._document.querySelector(
      '.oui-select-panel'
    ) as HTMLElement;
    const selectSearchBox = this._document.querySelector(
      '.oui-select-search-inner'
    ) as HTMLElement;
    const selectOptionsWrapper = this._document.querySelector(
      '.oui-select-options-wrapper'
    ) as HTMLElement;
    const labelHeight = labelCount ? (labelCount - 1) * 10 : 0;
    const optionHeight = selectedOption?.clientHeight || SELECT_OPTION_HEIGHT;
    const ouiSelectActionWrapperHeight =
      selectActionWrapperElement?.clientHeight ?? 0;
    const selectSearchBoxheight = selectSearchBox?.clientHeight - 10 || 0;
    const selectPanelHeight =
      selectPanelElement?.clientHeight -
        ouiSelectActionWrapperHeight -
        selectSearchBoxheight -
        20 -
        labelHeight || SELECT_PANEL_HEIGHT;
    const selectOptionsWrapperRect =
      selectOptionsWrapper?.getBoundingClientRect();
    const selectedOptionRect = selectedOption?.getBoundingClientRect();
    const selectedOptionOffset =
      selectedOptionRect?.top -
      selectSearchBoxheight -
      selectOptionsWrapperRect?.top -
      10;
    const scrollTop = this._getScrollTop();
    const newScrollPosition = _getOptionScrollPosition(
      index + labelCount,
      optionHeight,
      scrollTop,
      selectPanelHeight,
      selectedOptionOffset
    );
    this._setScrollTop(newScrollPosition);
  }

  /**
   * Sets the panel scrollTop. This allows us to manually scroll to display options
   * above or below the fold, as they are not actually being focused when active.
   */
  _setScrollTop(scrollTop: number): void {
    if (this.panel) {
      this.panel.nativeElement.querySelector('.oui-select-options').scrollTop =
        scrollTop;
    }
  }

  /** Returns the panel's scrollTop. */
  _getScrollTop(): number {
    return this.panel
      ? this.panel.nativeElement.querySelector('.oui-select-options').scrollTop
      : 0;
  }
}

styleUrlsData.data:
@use 'sass:math';

@import '../core/style/menu-common';
@import '../core/style/list-common';
@import '../core/style/variables';
@import '../core/style/vendor-prefixes';
$oui-select-arrow-size: 5px !default;
$oui-select-arrow-margin: 4px !default;
$oui-select-panel-max-height: 256px !default;
$oui-select-item-height: 40px !default;
$oui-select-placeholder-arrow-space: 2 *
  ($oui-select-arrow-size + $oui-select-arrow-margin);
$gray-color: #eee;

%placeholder {
  font-size: 14px;
}

.oui-error {
  @extend %placeholder;
}
.oui-select {
  display: inline-block;
  width: 100%;
  outline: none;
  div {
    margin: 0;
    vertical-align: middle;
  }
  .oui-select-value {
    @extend %placeholder;
    line-height: 19px;
    padding: 2px 8px 2px 0;
  }
}

.oui-select-trigger {
  display: inline-table;
  cursor: pointer;
  position: relative;
  box-sizing: border-box;

  .oui-select-disabled & {
    @include user-select(none);
    cursor: default;
  }
}

.oui-select-value {
  display: table-cell;
  max-width: 0;
  width: 100%;
}

.oui-select-value-text {
  display: inline-block;
  width: 100%;
  @include oui-truncate-line();
  span img {
    max-width: 20px;
    max-height: 20px;
  }
}

.oui-select-arrow-wrapper {
  display: inline-block;
  vertical-align: middle;

  // When used in a box appearance form-field the arrow should be shifted up 50%.
  .oui-form-field-appearance-fill & {
    transform: translateY(-50%);
  }

  // When used in a outline form-field the arrow should be shifted up 25%.
  .oui-form-field-appearance-outline & {
    transform: translateY(-25%);
  }

  // Animate the arrow position, but only when the transitioning to empty (animate the arrow down)
  // This is in line with the oui-form-field label animation
  .oui-form-field-appearance-standard .oui-select.oui-select-empty & {
    transition: transform $swift-ease-out-duration
      $swift-ease-out-timing-function;
  }

  ._oui-animation-noopable.oui-form-field-appearance-standard
    .oui-select.oui-select-empty
    & {
    transition: none;
  }
}

.oui-select-arrow {
  width: 12px;
}

.oui-focused {
  .oui-select-arrow {
    transform: rotate(180deg);
  }
  .oui-select.oui-input:not(.oui-select-list-options-opened) {
    .oui-select-arrow {
      transform: rotate(0deg);
    }
  }
}

.oui-select-large {
  max-height: 392px !important;
}

// Override optgroup and option to scale based on font-size of the trigger.
.oui-select-panel {
  color: #333;
  -webkit-overflow-scrolling: touch; // for momentum scroll on mobile
  overflow-x: hidden;
  padding-bottom: 0;
  position: relative;
  border: 1px solid #c8c8c8;
  background-color: #ffffff;
  max-height: 272px;
  margin: 6px 0 0 -10px;
  box-sizing: border-box;
  min-width: 100px;
  font-family: 'Open Sans', Helvetica, Arial, sans-serif;
  box-shadow: 0 2px 4px -1px rgba(0, 0, 0, 0.2), 0 4px 5px 0 rgba(0, 0, 0, 0.14),
    0 1px 10px 0 rgba(0, 0, 0, 0.12);
  border-top: 0;
  .oui-select-options {
    -webkit-overflow-scrolling: touch; // for momentum scroll on mobile
    overflow-x: hidden;
    height: 100%;
    padding-top: 10px;
    box-sizing: border-box;
  }
  &.oui-select-input-outer {
    .oui-select-options {
      padding-top: 0px;
    }
  }
  &.action-item,
  &.single-action-item {
    padding-bottom: 56px;
  }
  .oui-option {
    line-height: $oui-select-item-height;
    height: $oui-select-item-height;
    padding: 0 10px;
    font-size: 14px;
    &.oui-active {
      background: $gray-color;
      color: #333;
    }
    &.oui-option-disabled {
      color: rgba(0, 0, 0, 0.38);
    }
    &:last-child {
      margin-bottom: 10px;
    }
    oui-checkbox {
      width: 100%;
      label {
        width: 100%;
        display: block;
      }
    }
  }
  .oui-option-multiple.oui-selected,
  .oui-option-multiple.oui-active {
    background: none;
  }
  .oui-optgroup-label {
    font-weight: 700;
    display: block;
    padding: 0 10px;
    font-size: 14px;
    line-height: $oui-select-item-height;
  }
}

.oui-form-field-type-oui-select {
  &:not(.oui-form-field-disabled) .oui-form-field-flex {
    cursor: pointer;
  }

  .oui-form-field-label {
    width: calc(100% - #{$oui-select-placeholder-arrow-space});
  }
}

.oui-select-placeholder {
  // Delay the transition until the label has animated about a third of the way through, in
  // order to prevent the placeholder from overlapping for a split second.
  @include oui-truncate-line();
  display: inline-block;
  width: 100%;
  transition: color $swift-ease-out-duration
    math.div($swift-ease-out-duration, 3) $swift-ease-out-timing-function;
  color: #666;
  ._oui-animation-noopable & {
    transition: none;
  }

  .oui-form-field-hide-placeholder & {
    color: transparent;

    // Overwrite browser specific CSS properties that can overwrite the `color` property.
    // Some developers seem to use this approach to easily overwrite the placeholder / label color.
    -webkit-text-fill-color: transparent;

    // Remove the transition to prevent the placeholder
    // from overlapping when the label comes back down.
    transition: none;
    // Prevents the '...' from showing on the parent element.
    display: block;
  }
}
