  .oui-select.oui-input.oui-select-inline-edit {
  border: none !important;
  border-bottom: 1px solid transparent !important;

  &:after {
    background: transparent !important;
  }
}

/*-- search dropdown underline --*/

.oui-option:focus:not(.oui-option-disabled),
.oui-option:hover:not(.oui-option-disabled),
.oui-option.oui-selected:not(.oui-option-multiple):not(.oui-option-disabled) {
  background: $gray-color;
}

.select-overlay-top.oui-select-panel {
  margin-bottom: 9px;
  border-top: 1px solid #c8c8c8;
}

.noResults {
  color: #333333;
  font-size: 14px;
  line-height: 22px;
  padding: 0 10px;
  margin: 17px 0 21px;
  word-break: break-all;
}

oui-select-search {
  height: 60px;
  display: block;
}
.oui-select-disabled .oui-select-placeholder {
  color: #9b9b9b;
}
.oui-select-action-wrapper {
  height: 56px;
  box-sizing: border-box;
  background: #fff;
  display: block;
  width: 100%;
  position: absolute;
  bottom: 0px;
  left: 0px;
}

.oui-select-action-items {
  position: absolute;
  border-top: 1px solid #ddd;
  height: 100%;
  padding: 10px;
  background: #fff;
  bottom: 1px;
  z-index: 100;
  box-sizing: border-box;
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  &.single-action-items {
    padding: 10px 0px !important;
    button {
      width: 100%;
      padding: 0px 10px !important;
      text-align: left;
      font-size: 14px;
      color: #333333 !important;
      border-radius: 0px;
      line-height: 40px;
      &:hover,
      &:focus {
        background-color: #eeeeee;
        box-shadow: none !important;
        text-decoration: none !important;
      }
    }
  }
}

