    height: 16px;
    background: #e8e8e8;
    border-radius: 50%;
    margin: 0px 0 0 5px;
    top: -1px;
    opacity: 0;
  }
}
.oui-sort-header-arrow-selected {
  height: 12px;
  width: 12px;
  background: $arrow-selected center center no-repeat;
  display: inline-block;
  margin: $arrow-margin;
  vertical-align: top;
  position: relative;
}
.oui-sort-header-arrow-faded {
  opacity: 0;
  height: 12px;
  width: 12px;
  background: $arrow-faded center center no-repeat;
  display: inline-block;
  margin: $arrow-margin;
  vertical-align: top;
  position: relative;
}
.oui-header-cell:hover .oui-sort-header-arrow-faded {
  opacity: 1;
}
.oui-header-cell {
  &[class^='cdk'],
