import {
  ChangeDetectionStrategy,
  Component,
  ContentChild,
  ElementRef,
  InjectionToken,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  SimpleChanges,
  TemplateRef,
  ViewChild,
  ViewContainerRef,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { OuiTabContent } from './tab-content';
import { OUI_TAB, OuiTabLabel } from './tab-label';
import { CanDisable, mixinColor } from '../core';
import { TemplatePortal } from '@angular/cdk/portal';
import { Subject } from 'rxjs';
import { DomSanitizer } from '@angular/platform-browser';

export class OuiTabsBase {
  constructor(public _elementRef: ElementRef) {}
}
// Boilerplate for applying mixins to OuiTab.
/** @docs-private */
const _OuiTabMixinBase: typeof OuiTabsBase = mixinColor(OuiTabsBase);

/**
 * Used to provide a tab group to a tab without causing a circular dependency.
 * @docs-private
 */
export const OUI_TAB_GROUP = new InjectionToken<any>('OUI_TAB_GROUP');

/** Default color palette for the tab */
const DEFAULT_COLOR = 'primary';

@Component({
  selector: 'oui-tab',
  // Note that usually we'd go through a bit more trouble and set up another class so that
  // the inlined template of `OuiTab` isn't duplicated, however the template is small enough
  // that creating the extra class will generate more code than just duplicating the template.
  templateUrl: 'tab.html',
  // eslint-disable-next-line @angular-eslint/no-inputs-metadata-property
  inputs: ['disabled'],
  // eslint-disable-next-line @angular-eslint/no-inputs-metadata-property
  changeDetection: ChangeDetectionStrategy.Default,
  encapsulation: ViewEncapsulation.None,
  exportAs: 'OuiTab',
  providers: [{ provide: OUI_TAB, useExisting: OuiTab }],
  standalone: false,
})
export class OuiTab
  extends _OuiTabMixinBase
  implements CanDisable, OnInit, OnChanges, OnDestroy
{
  private _viewContainerRef = inject(ViewContainerRef);
  _closestTabGroup = inject(OUI_TAB_GROUP, { optional: true })!;
  private sanitized = inject(DomSanitizer);

  /** Content for the tab label given by `<ng-template oui-tab-label>`. */
  private _templateLabel: OuiTabLabel;
  disabled: any;
  @ContentChild(OuiTabLabel)
  get templateLabel(): OuiTabLabel {
    return this._templateLabel;
  }
  set templateLabel(value: OuiTabLabel) {
    this._setTemplateLabelInput(value);
  }

  /**
   * Template provided in the tab content that will be used if present, used to enable lazy-loading
   */
  @ContentChild(OuiTabContent, { read: TemplateRef, static: true })
  // We need an initializer here to avoid a TS error. The value will be set in `ngAfterViewInit`.
  private _explicitContent: TemplateRef<any> = undefined!;

  /** Template inside the OuiTab view that contains an `<ng-content>`. */
  @ViewChild(TemplateRef, { static: true }) _implicitContent: TemplateRef<any>;

  /** Plain text label for the tab, used when there is no template label. */
  @Input('label') textLabel = '';

  contentWithin = '';

  /** Aria label for the tab. */
  @Input('aria-label') ariaLabel: string;

  @Input() color = 'accent';

  /**
   * Reference to the element that the tab is labelled by.
   * Will be cleared if `aria-label` is set at the same time.
   */
  @Input('aria-labelledby') ariaLabelledby: string;

  /**
   * Classes to be passed to the tab label inside the oui-tab-header container.
   * Supports string and string array values, same as `ngClass`.
   */
  @Input() labelClass: string | string[];

  /**
   * Classes to be passed to the tab oui-tab-body container.
   * Supports string and string array values, same as `ngClass`.
   */
  @Input() bodyClass: string | string[];

  /** Portal that will be the hosted content of the tab */
  private _contentPortal: TemplatePortal | null = null;

  /** @docs-private */
  get content(): TemplatePortal | null {
    return this._contentPortal;
  }

  /** Emits whenever the internal state of the tab changes. */
  readonly _stateChanges = new Subject<void>();

  /**
   * The relatively indexed position where 0 represents the center, negative is left, and positive
   * represents the right.
   */
  position: number | null = null;

  /**
   * The initial relatively index origin of the tab if it was created and selected after there
   * was already a selected tab. Provides context of what position the tab should originate from.
   */
  origin: number | null = null;

  /**
   * Whether the tab is currently active.
   */
  isActive = false;

  @ViewChild('tab1') _tab1: ElementRef;

  constructor() {
    const _elementRef = inject(ElementRef);

    super(_elementRef);
    this.addThemeColor();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (
      Object.prototype.hasOwnProperty.call(changes, 'textLabel') ||
      Object.prototype.hasOwnProperty.call(changes, 'disabled')
    ) {
      setTimeout(() => {
        this.contentWithin = this.sanitized.bypassSecurityTrustHtml(
          // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
          this._elementRef.nativeElement.innerHTML
        )['changingThisBreaksApplicationSecurity'];
      });
      this._stateChanges.next();
    }
    if (
      Object.prototype.hasOwnProperty.call(changes, '_tab2') ||
      Object.prototype.hasOwnProperty.call(changes, 'disabled')
    ) {
      this._stateChanges.next();
    }
  }

  addThemeColor() {
    if (!this.color) {
      this.color = DEFAULT_COLOR;
    }
  }

  ngOnDestroy(): void {
    this._stateChanges.complete();
  }

  ngOnInit(): void {
    setTimeout(() => {
      this.contentWithin = this.sanitized.bypassSecurityTrustHtml(
        // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
        this._elementRef.nativeElement.innerHTML
      )['changingThisBreaksApplicationSecurity'];
    });
    this._contentPortal = new TemplatePortal(
      this._explicitContent || this._implicitContent,
      this._viewContainerRef,
      this._tab1
    );
  }

  /**
   * This has been extracted to a util because of TS 4 and VE.
   * View Engine doesn't support property rename inheritance.
   * TS 4.0 doesn't allow properties to override accessors or vice-versa.
   * @docs-private
   */
  private _setTemplateLabelInput(value: OuiTabLabel | undefined) {
    // Only update the label if the query managed to find one. This works around an issue where a
    // user may have manually set `templateLabel` during creation mode, which would then get
    // clobbered by `undefined` when the query resolves. Also note that we check that the closest
    // tab matches the current one so that we don't pick up labels from nested tabs.
    if (value && value._closestTab === this) {
      this._templateLabel = value;
    }
  }
}

import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ComponentFactoryResolver,
  Directive,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild,
  ViewContainerRef,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { CdkPortalOutlet } from '@angular/cdk/portal';
import { Direction, Directionality } from '@angular/cdk/bidi';
import { DOCUMENT } from '@angular/common';
import { Subject, Subscription } from 'rxjs';
import {
  distinctUntilChanged,
  // startWith
} from 'rxjs/operators';
import { AnimationEvent } from '@angular/animations';
import { ouiTabsAnimations } from './tabs-animations';
import { DomSanitizer } from '@angular/platform-browser';

/**
 * The portal host directive for the contents of the tab.
 * @docs-private
 */

@Directive({
  // eslint-disable-next-line @angular-eslint/directive-selector
  selector: `OuiTabBodyHost`,
  standalone: false,
})
export class OuiTabBodyPortal
  extends CdkPortalOutlet
  implements OnInit, OnDestroy
{
  /** Subscription to events for when the tab body begins centering. */
  private _centeringSub = Subscription.EMPTY;
  /** Subscription to events for when the tab body finishes leaving from center position. */
  private _leavingSub = Subscription.EMPTY;

  constructor() {
    const componentFactoryResolver = inject(ComponentFactoryResolver);
    const viewContainerRef = inject(ViewContainerRef);
    const _document = inject(DOCUMENT);

    super(componentFactoryResolver, viewContainerRef, _document);
  }

  /** Set initial visibility or set up subscription for changing visibility. */
  override ngOnInit(): void {
    super.ngOnInit();
  }

  /** Clean up centering subscription. */
  override ngOnDestroy(): void {
    super.ngOnDestroy();
    this._centeringSub.unsubscribe();
    this._leavingSub.unsubscribe();
  }
}

/**
 * These position states are used internally as animation states for the tab body. Setting the
 * position state to left, right, or center will transition the tab body from its current
 * position to its respective state. If there is not current position (void, in the case of a new
 * tab body), then there will be no transition animation to its state.
 *
 * In the case of a new tab body that should immediately be centered with an animating transition,
 * then left-origin-center or right-origin-center can be used, which will use left or right as its
 * pseudo-prior state.
 */
export type OuiTabBodyPositionState =
  | 'left'
  | 'center'
  | 'right'
  | 'left-origin-center'
  | 'right-origin-center';

/**
 * Wrapper for the contents of a tab.
 * @docs-private
 */
@Component({
  selector: 'oui-tab-body',
  templateUrl: 'tab-body.html',
  // styleUrls: ['tab-body.css'],
  encapsulation: ViewEncapsulation.None,
  // tslint:disable-next-line:validate-decorators
  changeDetection: ChangeDetectionStrategy.Default,
  animations: [ouiTabsAnimations.translateTab],
  host: {
    class: 'oui-mdc-tab-body',
  },
  standalone: false,
})
export class OuiTabBody implements OnInit, OnDestroy, OnChanges {
  private _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  private _dir = inject(Directionality, { optional: true })!;
  private sanitized = inject(DomSanitizer);

  /** Current position of the tab-body in the tab-group. Zero means that the tab is visible. */
  private _positionIndex: number;

  /** Subscription to the directionality change observable. */
  private _dirChangeSubscription = Subscription.EMPTY;

  /** Tab body position state. Used by the animation trigger for the current state. */
  _position: OuiTabBodyPositionState;

  /** Emits when an animation on the tab is complete. */
  readonly _translateTabComplete = new Subject<AnimationEvent>();

  /** Event emitted when the tab begins to animate towards the center as the active tab. */
  @Output() readonly _onCentering: EventEmitter<number> =
    new EventEmitter<number>();

  /** Event emitted before the centering of the tab begins. */
  @Output() readonly _beforeCentering: EventEmitter<boolean> =
    new EventEmitter<boolean>();

  /** Event emitted before the centering of the tab begins. */
  @Output() readonly _afterLeavingCenter: EventEmitter<void> =
    new EventEmitter<void>();

  /** Event emitted when the tab completes its animation towards the center. */
  @Output() readonly _onCentered: EventEmitter<void> = new EventEmitter<void>(
    true
  );

  /** The portal host inside of this container into which the tab body content will be loaded. */
  @ViewChild(CdkPortalOutlet) _portalHost: CdkPortalOutlet;

  /** The tab body content to display. */
  @Input('content') _content: string;

  /** Position that will be used when the tab is immediately becoming visible after creation. */
  @Input() origin: number | null;

  // Note that the default value will always be overwritten by `OuiTabBody`, but we need one
  // anyway to prevent the animations module from throwing an error if the body is used on its own.
  /** Duration for the tab's animation. */
  @Input() animationDuration = '0ms';

  /** Whether the tab's content should be kept in the DOM while it's off-screen. */
  @Input() preserveContent = false;
  _innerContent: any;

  /** The shifted index position of the tab body, where zero represents the active center tab. */
  @Input()
  set position(position: number) {
    this._positionIndex = position;
    this._computePositionAnimationState();
  }

  constructor() {
    const _dir = this._dir;
    const changeDetectorRef = inject(ChangeDetectorRef);

    if (_dir) {
      this._dirChangeSubscription = _dir.change.subscribe((dir: Direction) => {
        this._computePositionAnimationState(dir);
        changeDetectorRef.markForCheck();
      });
    }

    // Ensure that we get unique animation events, because the `.done` callback can get
    // invoked twice in some browsers. See https://github.com/angular/angular/issues/24084.
    this._translateTabComplete
      .pipe(
        distinctUntilChanged((x, y) => {
          return x.fromState === y.fromState && x.toState === y.toState;
        })
      )
      .subscribe((event) => {
        // If the transition to the center is complete, emit an event.
        if (
          this._isCenterPosition(event.toState) &&
          this._isCenterPosition(this._position)
        ) {
          this._onCentered.emit();
        }

        if (
          this._isCenterPosition(event.fromState) &&
          !this._isCenterPosition(this._position)
        ) {
          this._afterLeavingCenter.emit();
        }
      });
  }

  /**
   * After initialized, check if the content is centered and has an origin. If so, set the
   * special position states that transition the tab from the left or right before centering.
   */
  ngOnInit() {
    if (this._position == 'center' && this.origin != null) {
      this._position = this._computePositionFromOrigin(this.origin);
    }
    this._innerContent = this.sanitized.bypassSecurityTrustHtml(
      this._content ? this._content : ''
    );
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes._content && changes._content.currentValue) {
      this._innerContent = this.sanitized.bypassSecurityTrustHtml(
        // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
        changes._content.currentValue ? changes._content.currentValue : ''
      );
    }
  }

  ngOnDestroy() {
    this._dirChangeSubscription.unsubscribe();
    this._translateTabComplete.complete();
  }

  _onTranslateTabStarted(event: AnimationEvent): void {
    const isCentering = this._isCenterPosition(event.toState);
    this._beforeCentering.emit(isCentering);
    if (isCentering) {
      this._onCentering.emit(this._elementRef.nativeElement.clientHeight);
    }
  }

  /** The text direction of the containing app. */
  _getLayoutDirection(): Direction {
    return this._dir && this._dir.value === 'rtl' ? 'rtl' : 'ltr';
  }

  /** Whether the provided position state is considered center, regardless of origin. */
  // eslint-disable-next-line @typescript-eslint/no-redundant-type-constituents
  _isCenterPosition(position: OuiTabBodyPositionState | string): boolean {
    return (
      position == 'center' ||
      position == 'left-origin-center' ||
      position == 'right-origin-center'
    );
  }

  /** Computes the position state that will be used for the tab-body animation trigger. */
  private _computePositionAnimationState(
    dir: Direction = this._getLayoutDirection()
  ) {
    if (this._positionIndex < 0) {
      this._position = dir == 'ltr' ? 'left' : 'right';
    } else if (this._positionIndex > 0) {
      this._position = dir == 'ltr' ? 'right' : 'left';
    } else {
      this._position = 'center';
    }
  }

  /**
   * Computes the position state based on the specified origin position. This is used if the
   * tab is becoming visible immediately after creation.
   */
  private _computePositionFromOrigin(origin: number): OuiTabBodyPositionState {
    const dir = this._getLayoutDirection();

    if ((dir == 'ltr' && origin <= 0) || (dir == 'rtl' && origin > 0)) {
      return 'left-origin-center';
    }

    return 'right-origin-center';
  }
}

/**
 * The origin state is an internally used state that is set on a new tab body indicating if it
 * began to the left or right of the prior selected index. For example, if the selected index was
 * set to 1, and a new tab is created and selected at index 2, then the tab body would have an
 * origin of right because its index was greater than the prior selected index.
 */
export type OuiTabBodyOriginState = 'left' | 'right';

import {
  AfterContentChecked,
  AfterContentInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChildren,
  ElementRef,
  EventEmitter,
  Input,
  OnDestroy,
  Output,
  QueryList,
  ViewChild,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { ANIMATION_MODULE_TYPE } from '@angular/platform-browser/animations';
import { OUI_TAB_GROUP, OuiTab } from './tab';
import { OuiTabHeader } from './tab-header';
import {
  BooleanInput,
  coerceBooleanProperty,
  coerceNumberProperty,
  NumberInput,
} from '@angular/cdk/coercion';
import {
  CanColor,
  CanDisableRipple,
  mixinColor,
  mixinDisableRipple,
  ThemePalette,
} from '../core';
import { merge, Subscription } from 'rxjs';
import { OUI_TABS_CONFIG, OuiTabsConfig } from './tab-config';
import { startWith } from 'rxjs/operators';
import { FocusOrigin } from '@angular/cdk/a11y';

