import {
  CdkTable,
  CDK_TABLE,
  STICKY_POSITIONING_LISTENER,
} from '@angular/cdk/table';
import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  ViewEncapsulation,
} from '@angular/core';

/**
 * NOTE: This directive was previously used to enable a recycle view repeater strategy
 * (reducing rendering latency). With Angular CDK 21 the repeater strategy provider/token
 * is no longer provided here, so this directive is currently a no-op and does not
 * change rendering behavior.
 *
 * Keep the directive in place for compatibility, but do not rely on it for performance
 * improvements. If you need a recycle strategy with CDK 21, provide the appropriate
 * strategy implementation via the CDK token in your application.
 *
 * @deprecated no-op as of CDK 21
 */
@Directive({
  selector: 'oui-table[recycleRows], table[oui-table][recycleRows]',
  standalone: false,
})
export class MatRecycleRows {}

/**
 * Wrapper for the CdkTable with Once-UI design styles.
 */
@Component({
  selector: 'oui-table, table[oui-table]',
  exportAs: 'ouiTable',
  template: `
    <ng-content select="caption"></ng-content>
    <ng-content select="colgroup, col"></ng-content>
    <ng-container headerRowOutlet></ng-container>
    <ng-container rowOutlet></ng-container>
    <ng-container noDataRowOutlet></ng-container>
    <ng-container footerRowOutlet></ng-container>
  `,
  styleUrls: ['table.scss'],
  host: {
    class: 'oui-table',
    '[class.oui-table-fixed-layout]': 'fixedLayout',
  },
  providers: [
    { provide: CdkTable, useExisting: OuiTable },
    { provide: CDK_TABLE, useExisting: OuiTable },
    // Prevent nested tables from seeing this table's StickyPositioningListener.
    { provide: STICKY_POSITIONING_LISTENER, useValue: null },
  ],
  encapsulation: ViewEncapsulation.None,
  // See note on CdkTable for explanation on why this uses the default change detection strategy.
  // eslint:disable-next-line:validate-decorators
  changeDetection: ChangeDetectionStrategy.Default,
  standalone: false,
})
export class OuiTable<T> extends CdkTable<T> {
  /** Overrides the sticky CSS class set by the `CdkTable`. */
  protected override stickyCssClass = 'oui-table-sticky';

  /** Overrides the need to add position: sticky on every sticky cell element in `CdkTable`. */
  protected override needsPositionStickyOnElement = false;
}

styleUrlsData.data:
$oui-header-row-height: 56px;
$oui-row-height: 48px;
$oui-row-horizontal-padding: 24px;
$oui-focus-color: #e8e8e8;
$oui-row-background-color: #f6f6f6;

/**
 * Flex-based table structure
 */
oui-table {
  display: block;
  border-spacing: 0;
}

oui-header-row {
  background-color: $oui-row-background-color;
  border-bottom: 1px solid #dfdfdf;
  border-top: 1px solid #dfdfdf !important;
}

oui-header-cell {
  padding: 16px 12.5px;
  font-size: 14px;
  font-weight: 700;
  line-height: 19px;
  color: #333;
  text-align: left;
  vertical-align: middle;
}

oui-cell {
  padding: 13px 12.5px;
  vertical-align: middle;
  font-size: 14px;
  color: #333;
  line-height: 20px;
}
.oui-row .oui-cell:nth-child(1),
.oui-header-row .oui-header-cell:nth-child(1) {
  padding-left: 16px;
}
.oui-row .oui-cell:nth-last-child(1),
.oui-header-row .oui-header-cell:nth-last-child(1) {
  padding-right: 16px;
}
oui-row,
oui-header-row,
oui-footer-row {
  display: flex;
  // Define a border style, but then widths default to 3px. Reset them to 0px except the bottom
  // which should be 1px;
  border-width: 0;
  border-bottom: 1px solid #dfdfdf;
  align-items: center;
  box-sizing: border-box;

  // Workaround for https://goo.gl/pFmjJD in IE 11. Adds a pseudo
  // element that will stretch the row the correct height. See:
  // https://connect.microsoft.com/IE/feedback/details/802625
  &::after {
    display: inline-block;
    min-height: inherit;
    content: '';
  }
}
oui-row {
  &:hover {
    background: $oui-row-background-color;
    cursor: pointer;
  }
  &[class^='cdk'],
  &[class$='focused'] {
    background: $oui-row-background-color;
    outline: none;
  }
}

td.oui-cell:focus {
  outline: none; // Removes the focus outline
}

oui-cell,
oui-header-cell,
oui-footer-cell {
  flex: 1;
  display: flex;
  align-items: center;
  overflow: hidden;
  word-wrap: break-word;
  min-height: inherit;
}

/**
 * Native HTML table structure
 */

table.oui-table {
  border-spacing: 0;
  border-collapse: collapse;
  width: 100%;
}

tr.oui-header-row {
  background-color: $oui-row-background-color;
  border-bottom: 1px solid #dfdfdf;
  border-top: 1px solid #dfdfdf;
}

th.oui-header-cell {
  padding: 16px 12.5px;
  font-size: 14px;
  font-weight: 700;
  line-height: 19px;
  color: #333;
  text-align: left;
  vertical-align: middle;
}
td.oui-cell {
  padding: 13px 12.5px;
  vertical-align: middle;
  font-size: 14px;
  color: #333;
  line-height: 20px;
}
tr.oui-row {
  border-bottom: 1px solid #dfdfdf;
  &:hover {
    background: $oui-row-background-color;
    cursor: pointer;
  }
  &[class^='cdk'],
  &[class$='focused'] {
    background: $oui-row-background-color;
    outline: none;
  }
}

