styleUrlsData.data:
.oui-mdc-tab-header {
  display: flex;
  overflow: hidden;
  position: relative;
  flex-shrink: 0;
  min-height: 48px;
  padding-top: 0;
  border-bottom: 1px solid #c8c8c8;
  justify-content: center;
}
.mdc-tab-indicator__content {
  transform-origin: left;
  opacity: 0;
}

.oui-mdc-tab-link.active .mdc-tab-indicator__content {
  opacity: 1;
}

.oui-mdc-tab-nav-bar[oui-align-tabs='start'] {
  justify-content: flex-start;
}
.oui-mdc-tab-nav-bar[oui-align-tabs='end'] {
  justify-content: flex-end;
}

.oui-mdc-tab-nav-bar[oui-stretch-tabs] {
  .oui-mdc-tab-links {
    display: flex;
  }
  .oui-mdc-tab-link-container {
    width: 100%;
  }
}

