import {
  AfterContentChecked,
  AfterContentInit,
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  ContentChildren,
  ElementRef,
  forwardRef,
  Input,
  OnDestroy,
  QueryList,
  ViewChild,
  ViewEncapsulation,
  inject,
  HostAttributeToken,
} from '@angular/core';
import { ANIMATION_MODULE_TYPE } from '@angular/platform-browser/animations';
import {
  CanDisable,
  CanDisableRipple,
  HasTabIndex,
  mixinDisabled,
  mixinDisableRipple,
  mixinTabIndex,
  ThemePalette,
} from '../../core';
import { FocusableOption, FocusMonitor } from '@angular/cdk/a11y';
import { OuiInkBar, mixinInkBarItem } from '../ink-bar';
import {
