    if (newValue !== this._isActive) {
      this._isActive = newValue;
      // Defer the updateActiveLink call to avoid ExpressionChangedAfterItHasBeenCheckedError
      Promise.resolve().then(() => this._tabNavBar.updateActiveLink());
